function load(){window.__dfLoadError=false;try{let raw=localStorage.getItem(KEY);if(raw)data=normalize(JSON.parse(raw));else{let old=localStorage.getItem('dentalflow_v1');data=old?normalize(JSON.parse(old)):blank();if(!save())throw new Error('Initial storage write failed')}if(migrateLegacyFollowups()&&!save())console.warn('Legacy follow-ups were migrated in memory but could not be persisted')}catch(e){console.error('DentalFlow data load failed; stored data was not overwritten',e);window.__dfLoadError=true;data=blank()}}
