function renderVisits(){var all=data.visits.slice().sort(function(x,y){return String(y.date||'').localeCompare(String(x.date||''))||String(y.time||'').localeCompare(String(x.time||''))});var el=$('visitList');if(!all.length){el.innerHTML='<div class="empty">No clinical visits yet.</div>';return}function card(v){var teeth='';(v.teeth||[]).forEach(function(t){teeth+='<span class="chip">'+esc(t.no)+' · '+esc(t.status)+'</span>'});var dx=v.diagnosis||v.reason||'Clinical visit';return '<div class="visit-card compact-patient-card df-context-row" data-df-type="visit" data-df-id="'+esc(v.id)+'" onclick="dfToggleInlineDetails(this.querySelector(\'.df-info-trigger\'))"><div class="df-row-main"><h4>'+esc(v.patientName)+' <span class="muted">'+esc(v.date||'')+'</span></h4><div class="muted">'+esc(dx)+(v.followup?' · Follow-up':'')+'</div></div><button type="button" class="df-info-trigger" aria-label="Visit details" title="Visit details" onclick="event.stopPropagation();dfToggleInlineDetails(this)">ⓘ</button><div class="tooth-summary compact-extra" hidden>'+teeth+'</div><div class="df-inline-details" hidden></div><div class="actions compact-extra df-inline-actions"><button class="df-action-icon" title="Open patient profile" aria-label="Open patient profile" onclick="event.stopPropagation();openProfile(\''+esc(v.patientId)+'\')">♙</button><button class="df-action-icon" title="Edit visit" aria-label="Edit visit" onclick="event.stopPropagation();openVisitEditForm(\''+esc(v.id)+'\')">✎</button></div></div>'}var today=day(),recentCutoff=new Date(today+'T12:00:00');recentCutoff.setDate(recentCutoff.getDate()-7);var cutoff=recentCutoff.getFullYear()+'-'+String(recentCutoff.getMonth()+1).padStart(2,'0')+'-'+String(recentCutoff.getDate()).padStart(2,'0');var todayRows=all.filter(function(v){return v.date===today}),recent=all.filter(function(v){return v.date&&v.date<today&&v.date>=cutoff}),older=all.filter(function(v){return !v.date||v.date<cutoff}),future=all.filter(function(v){return v.date>today});function dateSorted(rows){return rows.slice().sort(function(a,b){return String(b.date||'').localeCompare(String(a.date||''))||String(b.time||'').localeCompare(String(a.time||''))})}var html='';if(todayRows.length)html+=collapsibleDateGroup('Today',todayRows.length,dateSorted(todayRows).map(card).join(''),true,'visits:today','today');if(future.length)html+=collapsibleDateGroup('Future-dated visits',future.length,dateSorted(future).map(card).join(''),false,'visits:future','upcoming');if(recent.length)html+=collapsibleDateGroup('Recent Visits',recent.length,dateSorted(recent).map(card).join(''),true,'visits:recent','recent');if(older.length)html+=collapsibleDateGroup('Older Visits',older.length,dateSorted(older).map(card).join(''),false,'visits:older','older');el.innerHTML=html||'<div class="empty">No clinical visits yet.</div>'}
function openProfile(id){currentPatientId=id;switchView('profile');renderProfile(id)}
function patientContextData(pid){
 let p=patient(pid);if(!p)return null;
 let visits=data.visits.filter(function(v){return v.patientId===pid}).slice().sort(function(a,b){return (String(b.date)+' '+String(b.time||'')).localeCompare(String(a.date)+' '+String(a.time||''))});
 let plans=data.plans.filter(function(x){return x.patientId===pid&&['Completed','Cancelled'].indexOf(x.status)<0}).slice().sort(function(a,b){return String(b.createdAt||'').localeCompare(String(a.createdAt||''))});
 let due=data.bills.filter(function(b){return b.patientId===pid&&b.status!=='Cancelled'}).reduce(function(sum,b){updateBillStatus(b);return sum+billDue(b)},0);
 let follow=data.reminders.filter(function(r){return r.patientId===pid&&r.status!=='Done'}).slice().sort(function(a,b){return String(a.dueDate||'').localeCompare(String(b.dueDate||''))});
 let apps=data.appointments.filter(function(a){return a.patientId===pid&&a.date>=day()&&a.status!=='Cancelled'&&a.status!=='Completed'}).slice().sort(function(a,b){return (String(a.date)+' '+String(a.time||'')).localeCompare(String(b.date)+' '+String(b.time||''))});
 return {p:p,visits:visits,plans:plans,due:due,follow:follow,apps:apps};
}
function openPatientContext(pid){
 /* Unified patient flow: open the full patient hub directly. The context sheet remains in the code for compatibility, but is no longer a mandatory intermediate step. */
 if(!patient(pid))return;openProfile(pid);return;
 let d=patientContextData(pid);if(!d)return;currentPatientId=pid;let p=d.p,v=d.visits[0],pl=d.plans[0],r=d.follow[0],a=d.apps[0];
 $('patientContextContent').innerHTML='<div class="context-head"><div class="context-avatar">'+esc(initials(p.name))+'</div><div><div class="context-name">'+esc(p.name)+'</div><div class="muted">Patient ID: '+esc(p.id)+(p.phone?' · '+esc(p.phone):'')+'</div></div></div>'+
 '<div class="context-grid"><div class="context-stat"><b>Recent visit</b><span>'+(v?esc(v.date)+' · '+esc(v.diagnosis||v.reason||'Clinical visit'):'None yet')+'</span></div><div class="context-stat"><b>Active treatment plan</b><span>'+(pl?esc(pl.title)+' · '+esc(pl.status):'None')+'</span></div><div class="context-stat"><b>Due balance</b><span>₹ '+d.due.toLocaleString('en-IN')+'</span></div><div class="context-stat"><b>Next follow-up</b><span>'+(r?esc(r.dueDate||'No date')+' · '+esc(r.type||'Follow-up'):'None')+'</span></div><div class="context-stat"><b>Next appointment</b><span>'+(a?esc(a.date)+' · '+esc(a.time||'No time'):'None')+'</span></div><div class="context-stat"><b>Visits</b><span>'+d.visits.length+' recorded</span></div></div>'+
 (p.medical?'<div class="context-note"><b>Medical alert:</b> '+esc(p.medical)+'</div>':'')+
 '<div class="context-actions"><button class="context-action primary" onclick="patientContextAction(\'profile\')"><strong>👤 Profile</strong><small>Open full patient hub</small></button><button class="context-action" onclick="patientContextAction(\'visit\')"><strong>🦷 Clinical Visit</strong><small>Record today\'s visit</small></button><button class="context-action" onclick="patientContextAction(\'plan\')"><strong>📋 Treatment Plan</strong><small>Plan treatment for this patient</small></button><button class="context-action" onclick="patientContextAction(\'bill\')"><strong>💰 Billing</strong><small>Create or review billing</small></button><button class="context-action" onclick="patientContextAction(\'appointment\')"><strong>📅 Appointment</strong><small>Schedule / edit appointment</small></button><button class="context-action" onclick="patientContextAction(\'reminder\')"><strong>🔔 Follow-up</strong><small>Create or review reminder</small></button><button class="context-action" onclick="patientContextAction(\'record\')"><strong>📁 Patient Record</strong><small>Add a clinical document/note</small></button><button class="context-action" onclick="patientContextAction(\'edit\')"><strong>✎ Edit Patient</strong><small>Update demographic details</small></button></div>';
 openSheet('patientContextSheet');
}
function patientContextAction(action){closeSheet('patientContextSheet');var pid=currentPatientId;setTimeout(function(){if(action==='profile')openProfile(pid);else if(action==='visit')openVisitForm(pid);else if(action==='plan')openPlanForm(pid);else if(action==='bill')openBillForm(pid);else if(action==='appointment')openAppointmentForm('',pid);else if(action==='reminder')openReminderForm('',pid);else if(action==='record')openRecordForm('',pid);else if(action==='edit')openPatientForm(pid)},60)}
function openToothContext(pid,tooth){
 var p=patient(pid);if(!p||!tooth){toast('Select a patient and tooth / area first');return}currentPatientId=pid;var key=String(tooth).trim().toLowerCase();var re;try{re=new RegExp('(^|[^0-9])'+key.replace(/[.*+?^${}()|[\]\\]/g,'\\$&')+'([^0-9]|$)','i')}catch(e){re=null}
 var visits=data.visits.filter(function(v){if(v.patientId!==pid)return false;var structured=(v.teeth||[]).some(function(t){return String(t.no||'').trim().toLowerCase()===key});var text=[v.examination,v.diagnosis,v.treatmentDone,v.chiefComplaint,v.history].join(' ');return structured||(re&&re.test(text))}).slice().reverse();
 var plans=data.plans.filter(function(pl){return pl.patientId===pid&&(pl.items||[]).some(function(it){return String(it.tooth||'').trim().toLowerCase()===key||String(it.tooth||'').toLowerCase().indexOf(key)>=0})});
 var bills=data.bills.filter(function(b){return b.patientId===pid&&(b.items||[]).some(function(it){return String(it.tooth||'').trim().toLowerCase()===key||String(it.tooth||'').toLowerCase().indexOf(key)>=0})});
 var status=[];visits.forEach(function(v){(v.teeth||[]).forEach(function(t){if(String(t.no||'').trim().toLowerCase()===key)status.push({date:v.date,label:t.status||'Status recorded'})})});
 var html='<div class="context-head"><div class="context-avatar">🦷</div><div><div class="context-name">'+esc(tooth)+'</div><div class="muted">'+esc(p.name)+' · Patient ID '+esc(p.id)+'</div></div></div><div class="tooth-context-actions"><button class="btn" onclick="closeSheet(\'toothContextSheet\');openVisitForm(\''+esc(pid)+'\')">+ Clinical visit</button><button class="btn secondary" onclick="closeSheet(\'toothContextSheet\');openPlanForm(\''+esc(pid)+'\')">+ Treatment plan</button><button class="btn secondary" onclick="closeSheet(\'toothContextSheet\');openBillForm(\''+esc(pid)+'\')">+ Bill</button></div>';
 html+='<div class="tooth-context-block"><b>Recorded tooth status</b>'+(status.length?status.map(function(x){return '<div class="muted">'+esc(x.date)+' · '+esc(x.label)+'</div>'}).join(''):'<div class="muted">No structured tooth status recorded yet.</div>')+'</div>';
 html+='<div class="tooth-context-block"><b>Clinical history ('+visits.length+')</b>'+(visits.length?visits.map(function(v){return '<div class="tooth-context-block"><div class="muted">'+esc(v.date||'—')+' · Clinical visit</div><b>'+esc(v.diagnosis||'Diagnosis not recorded')+'</b>'+(v.examination?'<div class="muted">Examination: '+esc(v.examination)+'</div>':'')+(v.treatmentDone?'<div class="muted">Treatment: '+esc(v.treatmentDone)+'</div>':'')+(v.advice?'<div class="muted">Advice: '+esc(v.advice)+'</div>':'')+'</div>'}).join(''):'<div class="muted">No matching clinical visits found. Free-text matches are best-effort; review the full patient timeline if needed.</div>')+'</div>';
 html+='<div class="tooth-context-block"><b>Treatment plans ('+plans.length+')</b>'+(plans.length?plans.map(function(pl){return '<div class="muted">'+esc(pl.title)+' · '+esc(pl.status)+'</div>'+(pl.items||[]).filter(function(it){return String(it.tooth||'').trim().toLowerCase()===key||String(it.tooth||'').toLowerCase().indexOf(key)>=0}).map(function(it){return '<div>• '+esc(it.procedure)+' — '+esc(it.status||'Planned')+(it.estimate?' · ₹ '+Number(it.estimate).toLocaleString('en-IN'):'')+'</div>'}).join('')}).join(''):'<div class="muted">No matching planned treatment.</div>')+'</div>';
 html+='<div class="tooth-context-block"><b>Billing ('+bills.length+')</b>'+(bills.length?bills.map(function(b){return '<div class="muted">'+esc(b.date||'')+' · '+esc(b.status||'Bill')+' · ₹ '+billTotal(b).toLocaleString('en-IN')+'</div>'+(b.items||[]).filter(function(it){return String(it.tooth||'').trim().toLowerCase()===key||String(it.tooth||'').toLowerCase().indexOf(key)>=0}).map(function(it){return '<div>• '+esc(it.service)+' · ₹ '+(Number(it.amount||0)*Number(it.qty||1)).toLocaleString('en-IN')+'</div>'}).join('')}).join(''):'<div class="muted">No matching billing items.</div>')+'</div>';
 if(document.getElementById('visitSheet')&&document.getElementById('visitSheet').classList.contains('show'))html=html.replace(/<div class="tooth-context-actions">[\s\S]*?<\/div>/,'');$('toothContextContent').innerHTML=html;openSheet('toothContextSheet');
}

function renderProfile(id){
 let p=patient(id);if(!p)return;let ctx=patientContextData(id);
 let a=data.visits.filter(function(v){return v.patientId===id}).slice().reverse();
 let toothMap={};a.forEach(function(v){(v.teeth||[]).forEach(function(t){toothMap[t.no]=t.status})});
 let toothCount=Object.keys(toothMap).length;
 let planCount=data.plans.filter(function(x){return x.patientId===id}).length;
 let billCount=data.bills.filter(function(x){return x.patientId===id}).length;
 let recordCount=data.records.filter(function(x){return x.patientId===id}).length;
 let appointmentCount=data.appointments.filter(function(x){return x.patientId===id}).length;
 let timelineCount=a.length+planCount+billCount+recordCount+appointmentCount;
 let chart=toothCount?Object.keys(toothMap).sort(function(x,y){return Number(x)-Number(y)}).map(function(n){return '<button type="button" class="chip tooth-link" onclick="openToothContext(\''+esc(id)+'\',\''+esc(n)+'\')">'+esc(n)+' '+esc(toothMap[n])+'</button>'}).join(''):'<span class="muted">No tooth status recorded.</span>';
 let visitHtml=a.length?'<div class="list">'+a.map(function(v){return '<div class="visit-card profile-visit-card" role="button" tabindex="0" aria-label="Open clinical visit details" onclick="openContextDetail(\'visit\',\''+esc(v.id)+'\')" onkeydown="if(event.key===\'Enter\'||event.key===\' \'){event.preventDefault();openContextDetail(\'visit\',\''+esc(v.id)+'\')}"><h4>'+esc(v.date)+' • '+esc(v.time)+'</h4><div class="muted">'+esc(v.diagnosis||v.reason||'Clinical visit')+'</div>'+(v.chiefComplaint?'<p><b>CC:</b> '+esc(v.chiefComplaint)+'</p>':'')+(v.treatmentDone?'<p><b>Treatment:</b> '+esc(v.treatmentDone)+'</p>':'')+(v.prescription?'<p><b>Rx:</b> '+esc(v.prescription)+'</p>':'')+(v.advice?'<p><b>Advice:</b> '+esc(v.advice)+'</p>':'')+((v.teeth||[]).length?'<div>'+v.teeth.map(function(t){return '<button type="button" class="chip tooth-link" onclick="event.stopPropagation();openToothContext(\''+esc(id)+'\',\''+esc(t.no)+'\')">'+esc(t.no)+' '+esc(t.status)+'</button>'}).join('')+'</div>':'')+(v.nextVisit?'<p class="muted">Next visit: '+esc(v.nextVisit)+'</p>':'')+'</div>'}).join('')+'</div>':'<div class="empty">No clinical visits yet.</div>';
 $('profileContent').innerHTML='<div class="card"><div class="actions"><button class="btn ghost" onclick="switchView(\'patients\')">← Patients</button></div><div class="profile-head section"><div class="big-avatar">'+esc(initials(p.name))+'</div><div style="min-width:0"><div class="profile-name-row"><h2 style="margin:0">'+esc(p.name)+'</h2><button class="profile-edit-icon" aria-label="Edit patient details" title="Edit patient details" onclick="openPatientForm(\''+esc(p.id)+'\')"><svg viewBox="0 0 24 24"><path d="M12 20h9"></path><path d="M16.5 3.5a2.12 2.12 0 0 1 3 3L8 18l-4 1 1-4Z"></path></svg></button></div><div class="muted">Patient ID: '+esc(p.id)+'</div></div></div><div class="info-grid"><div class="info"><b>Phone</b><span>'+esc(p.phone||'Not added')+'</span></div><div class="info"><b>Age / Gender</b><span>'+esc(p.age||'—')+' / '+esc(p.gender||'—')+'</span></div><div class="info"><b>Address</b><span>'+esc(p.address||'Not added')+'</span></div><div class="info"><b>Medical alert</b><span>'+esc(p.medical||'None recorded')+'</span></div></div><div class="card section"><div class="section-title"><h3 style="margin:0">Patient overview</h3><span class="muted">Quick status</span></div><div class="context-grid"><div class="context-stat"><b>Recent visit</b><span>'+(ctx&&ctx.visits[0]?esc(ctx.visits[0].date)+' · '+esc(ctx.visits[0].diagnosis||ctx.visits[0].reason||'Clinical visit'):'No visit recorded')+'</span></div><div class="context-stat"><b>Next appointment</b><span>'+(ctx&&ctx.apps[0]?esc(ctx.apps[0].date)+' · '+esc(ctx.apps[0].time||'Time not set'):'None scheduled')+'</span></div><div class="context-stat"><b>Due balance</b><span>₹ '+(ctx?ctx.due:0).toLocaleString('en-IN')+'</span></div><div class="context-stat"><b>Next follow-up</b><span>'+(ctx&&ctx.follow[0]?esc(ctx.follow[0].dueDate||'Date not set')+' · '+esc(ctx.follow[0].type||'Follow-up'):'None pending')+'</span></div><div class="context-stat"><b>Active treatment plans</b><span>'+(ctx?ctx.plans.length:0)+' active</span></div><div class="context-stat"><b>Clinical visits</b><span>'+(ctx?ctx.visits.length:0)+' recorded</span></div></div></div></div>'+
 '<details class="card section profile-accordion"><summary><span>Current Tooth Status</span><span class="profile-count">'+toothCount+'</span></summary><div class="profile-accordion-content">'+chart+'</div></details>'+
 '<details class="card section profile-accordion" id="profilePlansSection"><summary><span>Treatment Plans</span><span class="profile-count">'+planCount+'</span></summary><div class="profile-accordion-content" id="profilePlans">'+renderPlansInline(p.id)+'</div></details>'+
 '<details class="card section profile-accordion" id="profileBillingSection"><summary><span>Billing &amp; Payments</span><span class="profile-count">'+billCount+'</span></summary><div class="profile-accordion-content" id="profileBilling">'+renderPatientBilling(p.id)+'</div></details>'+
 '<details class="card section profile-accordion" id="profileVisitHistory"><summary><span>Visit History</span><span class="profile-count">'+a.length+'</span></summary><div class="profile-accordion-content">'+visitHtml+'</div></details>'+
 '<details class="card section profile-accordion" id="patientTimelineSection"><summary><span>Timeline</span><span class="profile-count">'+timelineCount+'</span></summary><div class="profile-accordion-content"><div class="muted" style="margin:12px 0">Visits · plans · records · appointments · billing</div><div id="patientTimeline" class="history-mini"></div></div></details>'+
 '<div class="card section"><button class="btn danger" onclick="deletePatient(\''+esc(p.id)+'\')">Delete patient</button></div>';
 renderPatientTimeline(id);
}
function openPatientForm(id){editingPatientId=id||null;let p=id?patient(id):null;$('patientFormTitle').textContent=p?'Edit Patient':'New Patient';$('pName').value=p?p.name:'';$('pAge').value=p?p.age:'';$('pGender').value=p?p.gender:'';$('pPhone').value=p?p.phone:'';$('pAddress').value=p?p.address:'';$('pMedical').value=p?p.medical:'';$('patientSheet').classList.add('show');setTimeout(function(){$('pName').focus()},60)}
function savePatientForm(){let name=$('pName').value.trim();if(!name){alert('Patient name is required.');return}let p=editingPatientId?patient(editingPatientId):null;let wasNew=!p;if(!p){p={id:'P'+Date.now().toString(36).toUpperCase(),createdAt:new Date().toISOString()};data.patients.push(p)}Object.assign(p,{name:name,age:$('pAge').value.trim(),gender:$('pGender').value,phone:$('pPhone').value.trim(),address:$('pAddress').value.trim(),medical:$('pMedical').value.trim()});save();closeSheet('patientSheet');editingPatientId=null;render();toast(wasNew?'Patient added':'Patient updated');if(wasNew)openProfile(p.id)}
function deletePatient(id){if(!confirm('Delete this patient and their stored visits, plans, bills, appointments, records and reminders?'))return;data.patients=data.patients.filter(function(p){return p.id!==id});data.visits=data.visits.filter(function(v){return v.patientId!==id});data.plans=data.plans.filter(function(pl){return pl.patientId!==id});data.bills=data.bills.filter(function(b){return b.patientId!==id});data.appointments=data.appointments.filter(function(a){return a.patientId!==id});data.records=data.records.filter(function(r){return r.patientId!==id});data.reminders=data.reminders.filter(function(r){return r.patientId!==id});save();currentPatientId=null;switchView('patients');toast('Patient and associated records deleted')}
function fillClinicalPickers(){let nums=[];[11,21,31,41].forEach(function(start){for(let i=0;i<8;i++)nums.push(String(start+i))});let opts='<option value="">Tooth</option>'+nums.map(function(n){return '<option value="'+n+'">'+n+'</option>'}).join('');['examTooth','dxTooth','txTooth'].forEach(function(id){$(id).innerHTML=opts});let exam=['General finding'].concat(TOOTH_STATUSES);let dx=['Diagnosis','Caries','Pulpitis','Necrosis','Apical periodontitis','Gingivitis','Periodontitis','Fracture','Impacted tooth','Missing tooth','Other'];let tx=['Treatment','Restoration','RCT','Obturation','Crown','Extraction','Scaling','Filling','Prosthesis','Temporary dressing','Other'];[['examFinding',exam],['dxFinding',dx],['txFinding',tx]].forEach(function(x){$(x[0]).innerHTML='<option value="">Problem / action</option>'+x[1].map(function(v){return '<option>'+esc(v)+'</option>'}).join('')})}





let wfNewPatient=false;
const WF_DRAFT_KEY='dentalflow_workflow_draft_v1';
const WF_DRAFT_FIELDS=['wfPatient','wfName','wfAge','wfGender','wfPhone','wfAddress','wfMedical','wfArrival','wfAptDate','wfAptTime','wfAptNote','wfChief','wfHistory','wfExam','wfDiagnosis','wfTreatment','wfRx','wfAdvice','wfNext','wfNextTime','wfPaid','wfMode','wfDiscount'];
let wfDraftTimer=null;
function workflowDraftHasContent(d){return !!(d&&(d.newPatient||(Array.isArray(d.billItems)&&d.billItems.length)||['wfName','wfPhone','wfAddress','wfMedical','wfAptNote','wfChief','wfHistory','wfExam','wfDiagnosis','wfTreatment','wfRx','wfAdvice','wfNext','wfPaid','wfDiscount'].some(function(k){return String((d.fields||{})[k]||'').trim()})))}
function collectWorkflowDraft(){let fields={};WF_DRAFT_FIELDS.forEach(function(id){let el=$(id);if(el)fields[id]=el.value});return{savedAt:new Date().toISOString(),newPatient:!!wfNewPatient,patientId:$('workflowSheet').dataset.patientId||'',fields:fields,billItems:JSON.parse(JSON.stringify(wfBillItems||[]))}}
function saveWorkflowDraftSoon(){clearTimeout(wfDraftTimer);wfDraftTimer=setTimeout(function(){if(!$('workflowSheet')||!$('workflowSheet').classList.contains('show'))return;let d=collectWorkflowDraft();if(!workflowDraftHasContent(d)){if($('wfDraftStatus'))$('wfDraftStatus').textContent='Draft stays on this device while you work.';return}try{localStorage.setItem(WF_DRAFT_KEY,JSON.stringify(d));if($('wfDraftStatus'))$('wfDraftStatus').textContent='Draft saved on this device · '+new Date().toLocaleTimeString([],{hour:'2-digit',minute:'2-digit'});}catch(e){if($('wfDraftStatus'))$('wfDraftStatus').textContent='Draft could not be saved — finish or export your clinic data.';console.warn('Workflow draft save failed',e)}},350)}
function restoreWorkflowDraft(d){if(!d||!d.fields)return;wfNewPatient=!!d.newPatient;$('wfNewPatientFields').style.display=wfNewPatient?'block':'none';$('wfPatient').disabled=wfNewPatient;$('wfNewToggle').textContent=wfNewPatient?'Use existing patient':'＋ New patient';WF_DRAFT_FIELDS.forEach(function(id){let el=$(id);if(el&&Object.prototype.hasOwnProperty.call(d.fields,id)){if(id==='wfPatient'&&d.fields[id]&&!patient(d.fields[id]))return;el.value=d.fields[id]}});$('wfAppointmentFields').style.display=$('wfArrival').value==='Appointment'?'block':'none';$('workflowSheet').dataset.patientId=d.patientId||'';wfBillItems=Array.isArray(d.billItems)?d.billItems.filter(function(x){return x&&String(x.service||'').trim()&&Number.isFinite(Number(x.fee))&&Number(x.fee)>=0}).map(function(x){return{service:String(x.service),fee:Number(x.fee)}}):[];renderWorkflowBillItems();if($('wfDraftStatus'))$('wfDraftStatus').textContent='Recovered draft from '+(d.savedAt?new Date(d.savedAt).toLocaleString():'earlier')+'.';}
function discardWorkflowDraft(){clearTimeout(wfDraftTimer);try{localStorage.removeItem(WF_DRAFT_KEY)}catch(e){}WF_DRAFT_FIELDS.forEach(function(id){let el=$(id);if(el)el.value=''});wfBillItems=[];if($('wfServiceEntry'))$('wfServiceEntry').value='';if($('wfServiceFee'))$('wfServiceFee').value='';renderWorkflowBillItems();wfNewPatient=false;$('wfNewPatientFields').style.display='none';$('wfPatient').disabled=false;$('wfNewToggle').textContent='+ New patient';$('wfAppointmentFields').style.display='none';if($('wfDraftStatus'))$('wfDraftStatus').textContent='Draft discarded. You can start again.';toast('Workflow draft discarded')}
function initWorkflowDraftRecovery(){WF_DRAFT_FIELDS.forEach(function(id){let el=$(id);if(el){el.addEventListener('input',saveWorkflowDraftSoon);el.addEventListener('change',saveWorkflowDraftSoon)}});}
let wfBillItems=[];
function workflowBillTotal(){return wfBillItems.reduce(function(sum,it){return sum+(Number(it.fee)||0)},0)}
function moneyWF(n){return '₹ '+Number(n||0).toLocaleString('en-IN',{maximumFractionDigits:2})}
function renderWorkflowBillItems(){let host=$('wfBillItems');if(!host)return;host.innerHTML=wfBillItems.map(function(it,i){return '<div class="wf-bill-line"><span class="wf-bill-name">'+esc(it.service)+'</span><span class="wf-bill-fee">'+moneyWF(it.fee)+'</span><button type="button" aria-label="Remove '+esc(it.service)+'" title="Remove item" onclick="removeWorkflowBillItem('+i+')">×</button></div>'}).join('');$('wfTotalDisplay').textContent=moneyWF(workflowBillTotal());updateWorkflowBillingSummary()}
function removeWorkflowBillItem(i){wfBillItems.splice(i,1);renderWorkflowBillItems();saveWorkflowDraftSoon()}
function addWorkflowBillItem(){let service=$('wfServiceEntry').value.trim(),feeText=$('wfServiceFee').value.trim(),fee=feeText===''?NaN:Number(feeText);if(!service){$('wfServiceEntry').focus();return false}if(!Number.isFinite(fee)||fee<0){toast('Enter a valid treatment fee');$('wfServiceFee').focus();return false}wfBillItems.push({service:service,fee:fee});$('wfServiceEntry').value='';$('wfServiceFee').value='';renderWorkflowBillItems();saveWorkflowDraftSoon();$('wfServiceEntry').focus();return true}
function updateWorkflowBillingSummary(){if(!$('wfNetPayable'))return;let total=workflowBillTotal(),discount=Math.max(0,Number($('wfDiscount').value)||0),paid=Math.max(0,Number($('wfPaid').value)||0);$('wfNetPayable').textContent=moneyWF(Math.max(0,total-discount));$('wfTotalReceived').textContent=moneyWF(paid);$('wfDueAmount').textContent=moneyWF(Math.max(0,total-discount-paid));}
function initWorkflowBilling(){
  let name=$('wfServiceEntry'),fee=$('wfServiceFee');
  if(!name||name.dataset.wfBillReady)return;
  name.dataset.wfBillReady='1';
  // Prevent Android keyboard's default "Next" action from skipping to Received Now.
  name.setAttribute('enterkeyhint','next');
  fee.setAttribute('enterkeyhint','done');
  fee.setAttribute('autocomplete','new-password');
  fee.setAttribute('autocorrect','off');
  fee.setAttribute('spellcheck','false');
  fee.setAttribute('data-no-suggest','true');
  function isEnter(e){return e.key==='Enter'||e.key==='NumpadEnter'||e.keyCode===13}
  name.addEventListener('keydown',function(e){
    if(isEnter(e)){e.preventDefault();e.stopPropagation();if(e.stopImmediatePropagation)e.stopImmediatePropagation();fee.focus();}
  },true);
  fee.addEventListener('keydown',function(e){
    if(isEnter(e)){e.preventDefault();e.stopPropagation();if(e.stopImmediatePropagation)e.stopImmediatePropagation();addWorkflowBillItem();}
  },true);
  // Some Android numeric keyboards dispatch a focus/Next action instead of a normal Enter key.
  // If a complete service+fee pair loses focus, commit it and return to the service field.
  fee.addEventListener('blur',function(){
    if(fee.dataset.wfCommitting==='1')return;
    let service=name.value.trim(),raw=fee.value.trim(),amount=raw===''?NaN:Number(raw);
    if(!service||!Number.isFinite(amount)||amount<0)return;
    fee.dataset.wfCommitting='1';
    setTimeout(function(){
      try{
        if(name.value.trim()&&fee.value.trim()!==''&&Number.isFinite(Number(fee.value))&&Number(fee.value)>=0){
          addWorkflowBillItem();
        }
      }finally{fee.dataset.wfCommitting='';}
    },80);
  });
  $('wfPaid').addEventListener('input',updateWorkflowBillingSummary);
  $('wfDiscount').addEventListener('input',updateWorkflowBillingSummary);
}
function openUnifiedWorkflow(patientId){
  if(!$('workflowSheet'))return;initWorkflowBilling();
  wfNewPatient=false;$('wfNewPatientFields').style.display='none';$('wfNewToggle').textContent='+ New patient';
  $('wfPatient').innerHTML=data.patients.map(function(p){return '<option value="'+esc(p.id)+'">'+esc(p.name)+(p.phone?' — '+esc(p.phone):'')+'</option>'}).join('')||'<option value="">No saved patients</option>';
  if(patientId && patient(patientId))$('wfPatient').value=patientId;
  $('wfName').value='';$('wfAge').value='';$('wfGender').value='';$('wfPhone').value='';$('wfAddress').value='';$('wfMedical').value='';
  ['wfChief','wfHistory','wfExam','wfDiagnosis','wfTreatment','wfRx','wfAdvice','wfAptNote'].forEach(function(id){$(id).value=''});wfBillItems=[];renderWorkflowBillItems();$('wfServiceEntry').value='';$('wfServiceFee').value='';$('wfDiscount').value='';
  $('wfNext').value='';$('wfNextTime').value='';$('wfPaid').value='';$('wfMode').value=data.settings.defaultPaymentMode||'Cash';$('wfArrival').value='Walk-in';$('wfAptDate').value=day();$('wfAptTime').value='';$('wfAppointmentFields').style.display='none';
  $('wfArrival').onchange=function(){$('wfAppointmentFields').style.display=this.value==='Appointment'?'block':'none'};
  $('workflowSheet').dataset.patientId=patientId||'';
  if($('wfDraftStatus'))$('wfDraftStatus').textContent='Draft stays on this device while you work.';renderWorkflowBillItems();
  let draft=null;try{draft=JSON.parse(localStorage.getItem(WF_DRAFT_KEY)||'null')}catch(e){}
  if(workflowDraftHasContent(draft)){
    if(confirm('A saved Patient Workflow draft was found ('+(draft.savedAt?new Date(draft.savedAt).toLocaleString():'saved earlier')+'). Resume it?'))restoreWorkflowDraft(draft);
    else{try{localStorage.removeItem(WF_DRAFT_KEY)}catch(e){}}
  }
  openSheet('workflowSheet');
}
function toggleWorkflowNewPatient(){wfNewPatient=!wfNewPatient;$('wfNewPatientFields').style.display=wfNewPatient?'block':'none';$('wfPatient').disabled=wfNewPatient;$('wfNewToggle').textContent=wfNewPatient?'Use existing patient':'＋ New patient';if(wfNewPatient)setTimeout(function(){$('wfName').focus()},50)}
function saveUnifiedWorkflow(){
  var name=$('wfName').value.trim(),pid=wfNewPatient?'':$('wfPatient').value;
  if(wfNewPatient&&!name){alert('Please enter the patient name.');return}
  if(!wfNewPatient&&!patient(pid)){alert('Please select a patient or add a new patient.');return}
  var total=workflowBillTotal(),discount=Math.max(0,Number($('wfDiscount').value)||0),net=Math.max(0,total-discount),paidText=$('wfPaid').value.trim(),paid=paidText===''?0:Number(paidText);
  if(!Number.isFinite(total)||!Number.isFinite(discount)||!Number.isFinite(paid)||total<0||discount>total||paid<0||paid>net){alert('Please check the treatment fees, discount and payment. Discount cannot exceed total fee and payment cannot exceed net payable.');return}
  if((total>0)&&!wfBillItems.length){alert('Add a treatment/service and its fee before saving the bill.');return}
  var before=JSON.stringify(data),p,now=new Date(),visit=null,apt=null,bill=null,rem=null;
  try{
    if(wfNewPatient){p={id:'P'+Date.now().toString(36).toUpperCase(),createdAt:now.toISOString(),name:name,age:$('wfAge').value.trim(),gender:$('wfGender').value,phone:$('wfPhone').value.trim(),address:$('wfAddress').value.trim(),medical:$('wfMedical').value.trim()};data.patients.push(p);pid=p.id}
    else p=patient(pid);
    if(!p)throw new Error('Patient not found');
    var arrival=$('wfArrival').value;
    if(arrival==='Appointment'){
      apt={id:'A'+Date.now().toString(36),patientId:p.id,patientName:p.name,date:$('wfAptDate').value||day(),time:$('wfAptTime').value||'',reason:$('wfChief').value.trim()||$('wfTreatment').value.trim(),status:'In treatment',notes:$('wfAptNote').value.trim(),createdAt:now.toISOString(),visitId:''};data.appointments.push(apt);
    }
    var clinical=['wfChief','wfHistory','wfExam','wfDiagnosis','wfTreatment','wfRx','wfAdvice'].some(function(id){return $(id).value.trim()});
    if(clinical||arrival==='Walk-in'||arrival==='Appointment'){
      visit={id:'V'+Date.now().toString(36),patientId:p.id,patientName:p.name,date:day(),time:now.toLocaleTimeString([],{hour:'2-digit',minute:'2-digit'}),reason:$('wfDiagnosis').value.trim()||$('wfChief').value.trim()||'Clinical visit',followup:!!$('wfNext').value,chiefComplaint:$('wfChief').value.trim(),history:$('wfHistory').value.trim(),examination:$('wfExam').value.trim(),diagnosis:$('wfDiagnosis').value.trim(),treatmentDone:$('wfTreatment').value.trim(),advice:$('wfAdvice').value.trim(),prescription:$('wfRx').value.trim(),nextVisit:$('wfNext').value,nextVisitTime:$('wfNextTime').value||'',teeth:[],appointmentId:apt?apt.id:'',billId:'',reminderId:'',linkedPlanIds:[]};data.visits.push(visit);if(apt)apt.visitId=visit.id;
    }
    if(total>0){bill={id:'B'+Date.now().toString(36)+'W',patientId:p.id,patientName:p.name,date:day(),title:'Dental bill',status:'Open',notes:'',discount:discount,visitId:visit?visit.id:'',linkedVisitId:visit?visit.id:'',linkedPlanId:'',items:wfBillItems.map(function(it){return{id:'BI'+Date.now().toString(36)+Math.random().toString(36).slice(2,5),tooth:'',service:it.service,qty:1,amount:it.fee}}),payments:[]};if(paid>0)bill.payments.push({id:'PM'+Date.now().toString(36),date:day(),amount:paid,mode:$('wfMode').value||'Cash',note:'Payment received during patient workflow'});data.bills.push(bill);updateBillStatus(bill);if(visit)visit.billId=bill.id;}
    if(visit&&$('wfNext').value)ensureFollowupForVisit(visit);
    if(!save())throw new Error('Could not save to device storage. Please free device storage and retry.');
  }catch(e){try{data=normalize(JSON.parse(before))}catch(_){}console.error('Unified workflow save failed',e);alert(e.message||'Could not save this workflow. Your previous records have been kept.');return}
  clearTimeout(wfDraftTimer);try{localStorage.removeItem(WF_DRAFT_KEY)}catch(e){}closeSheet('workflowSheet');render();toast('Patient workflow saved');if(p&&p.id)openProfile(p.id);
}
