function addPlanItem(){let procedure=$('planProcedure').value.trim();if(!procedure){alert('Enter a procedure / service.');return}let estimate=parseFloat($('planEstimate').value)||0;planDraftItems.push({id:'I'+Date.now().toString(36),tooth:$('planTooth').value,procedure:procedure,priority:$('planPriority').value,estimate:estimate,status:'Planned',notes:$('planItemNotes').value.trim()});$('planTooth').value='';$('planProcedure').value='';$('planEstimate').value='';$('planItemNotes').value='';renderPlanItems()}
function renderPlanItems(){let el=$('planItems');if(!planDraftItems.length){el.innerHTML='<div class="empty">No treatment items added yet.</div>';return}el.innerHTML=planDraftItems.map(function(it,i){return '<div class="plan-item"><div class="plan-tooth">'+esc(it.tooth||'—')+'</div><div class="plan-main"><b>'+esc(it.procedure)+'</b><div class="muted">'+esc(it.priority)+(it.notes?' · '+esc(it.notes):'')+'</div><select class="status-select" onchange="planDraftItems['+i+'].status=this.value"><option '+(it.status==='Planned'?'selected':'')+'>Planned</option><option '+(it.status==='Discussed'?'selected':'')+'>Discussed</option><option '+(it.status==='Accepted'?'selected':'')+'>Accepted</option><option '+(it.status==='Scheduled'?'selected':'')+'>Scheduled</option><option '+(it.status==='In progress'?'selected':'')+'>In progress</option><option '+(it.status==='Completed'?'selected':'')+'>Completed</option><option '+(it.status==='Deferred'?'selected':'')+'>Deferred</option><option '+(it.status==='Declined'?'selected':'')+'>Declined</option></select></div><div><div class="plan-cost">'+(it.estimate?'₹ '+Number(it.estimate).toLocaleString('en-IN'):'—')+'</div><button type="button" class="btn danger" style="padding:5px 7px;font-size:10px;margin-top:5px" onclick="planDraftItems.splice('+i+',1);renderPlanItems()">×</button></div></div>'}).join('')+'<div class="plan-total"><span>Estimated total</span><span>₹ '+planDraftItems.reduce(function(a,b){return a+(Number(b.estimate)||0)},0).toLocaleString('en-IN')+'</span></div>'}
function saveTreatmentPlan(){let p=patient($('planPatient').value);if(!p){alert('Please select a patient.');return}if(!planDraftItems.length){alert('Add at least one treatment item.');return}let pl=editingPlanId?data.plans.find(function(x){return x.id===editingPlanId}):null;if(!pl){pl={id:'TP'+Date.now().toString(36),createdAt:new Date().toISOString(),items:[]};data.plans.push(pl)}var linkedVisitId=$('planSheet').dataset.linkedVisitId||'';var linkedVisits=Array.isArray(pl.linkedVisitIds)?pl.linkedVisitIds.slice():[];if(linkedVisitId&&linkedVisits.indexOf(linkedVisitId)<0)linkedVisits.push(linkedVisitId);Object.assign(pl,{patientId:p.id,title:$('planTitle').value.trim()||'Treatment Plan',status:$('planStatus').value,notes:$('planNotes').value.trim(),items:JSON.parse(JSON.stringify(planDraftItems)),linkedVisitIds:linkedVisits});if(linkedVisitId){var linkedVisit=data.visits.find(function(v){return v.id===linkedVisitId});if(linkedVisit){linkedVisit.linkedPlanIds=Array.isArray(linkedVisit.linkedPlanIds)?linkedVisit.linkedPlanIds:[];if(linkedVisit.linkedPlanIds.indexOf(pl.id)<0)linkedVisit.linkedPlanIds.push(pl.id)}}save();closeSheet('planSheet');$('planSheet').dataset.linkedVisitId='';editingPlanId=null;planDraftItems=[];currentPatientId=p.id;switchView('profile');toast('Treatment plan saved')}
function planTotal(pl){return(pl.items||[]).reduce(function(a,b){return a+(Number(b.estimate)||0)},0)}
function renderPlansInline(pid){let a=data.plans.filter(function(x){return x.patientId===pid}).slice().reverse();if(!a.length)return '<div class="empty">No treatment plan yet.</div>';return '<div class="history-mini">'+a.map(function(pl){let done=(pl.items||[]).filter(function(i){return i.status==='Completed'}).length;return '<div class="visit-card df-context-row" data-df-type="plan" data-df-id="'+esc(pl.id)+'"><div class="plan-summary"><b style="flex:1">'+esc(pl.title)+'</b><span class="plan-status">'+esc(pl.status)+'</span></div><div class="muted">'+done+'/'+pl.items.length+' items completed · Estimated ₹ '+planTotal(pl).toLocaleString('en-IN')+'</div>'+pl.items.map(function(it){var linkedApps=data.appointments.filter(function(ap){return ap.planId===pl.id&&ap.planItemId===it.id&&ap.status!=='Cancelled'}).sort(function(a,b){return String(a.date+' '+a.time).localeCompare(String(b.date+' '+b.time))});var appLabel=linkedApps.length?' · Appointment '+(linkedApps[0].date||'scheduled')+(linkedApps[0].time?' '+linkedApps[0].time:'')+(linkedApps.length>1?' · +'+(linkedApps.length-1)+' more':''):'';var itemActions=it.status==='Completed'?'':'<button type="button" class="btn ghost" style="padding:5px 8px;font-size:11px" onclick="schedulePlanItem(\''+esc(pid)+'\',\''+esc(pl.id)+'\',\''+esc(it.id)+'\')">'+(linkedApps.some(function(ap){return ap.status==='Scheduled'||ap.status==='Confirmed'})?'Schedule another':'Schedule appointment')+'</button>';return '<div class="plan-item"><div class="plan-tooth">'+esc(it.tooth||'—')+'</div><div class="plan-main"><b>'+esc(it.procedure)+'</b><div class="muted">'+esc(it.status)+' · '+esc(it.priority)+esc(appLabel)+'</div><div class="plan-actions" style="margin-top:5px">'+itemActions+(linkedApps.length?'<button type="button" class="btn ghost" style="padding:5px 8px;font-size:11px" onclick="openContextDetail(\'appointment\',\''+esc(linkedApps[0].id)+'\')">View appointment</button>':'')+'</div></div><div class="plan-cost">'+(it.estimate?'₹ '+Number(it.estimate).toLocaleString('en-IN'):'—')+'</div></div>'}).join('')+(pl.notes?'<div class="plan-note">'+esc(pl.notes)+'</div>':'')+'<div class="plan-actions"><button class="btn ghost" onclick="openContextDetail(\'plan\',\''+esc(pl.id)+'\')">Details</button><button class="btn secondary" onclick="openPlanForm(\''+esc(pid)+'\',\''+esc(pl.id)+'\')">Edit</button><button class="btn ghost" onclick="deletePlan(\''+esc(pl.id)+'\')">Delete</button></div></div>'}).join('')+'</div>'}
function schedulePlanItem(pid,planId,itemId){var pl=data.plans.find(function(x){return x.id===planId&&x.patientId===pid});if(!pl)return;var it=(pl.items||[]).find(function(x){return x.id===itemId});if(!it)return;if(it.status==='Completed'){toast('This treatment is already completed');return}openAppointmentForm('',pid);$('aptReason').value=(it.tooth?it.tooth+' — ':'')+it.procedure;$('aptNotes').value='Treatment plan: '+pl.title+' · Item: '+it.procedure+(it.tooth?' · Tooth/area '+it.tooth:'')+' · Plan item ID: '+it.id;$('appointmentFormTitle').textContent='Schedule treatment · '+(it.tooth?it.tooth+' — ':'')+it.procedure;$('appointmentSheet').dataset.planId=pl.id;$('appointmentSheet').dataset.planItemId=it.id;}
function openVisitFromAppointment(id){var a=appointmentById(id);if(!a)return;openVisitForm(a.patientId);$('visitChief').value=a.reason||'';if(a.planId&&a.planItemId){var pl=data.plans.find(function(x){return x.id===a.planId});var it=pl&&(pl.items||[]).find(function(x){return x.id===a.planItemId});if(it){$('visitTreatment').value=(it.tooth?it.tooth+' — ':'')+it.procedure;selectedTooth=it.tooth||null;}}$('visitSheet').dataset.appointmentId=a.id;$('visitSheet').dataset.planId=a.planId||'';$('visitSheet').dataset.planItemId=a.planItemId||'';toast('Appointment linked to a new clinical visit. Confirm findings and treatment before saving.')}
function deletePlan(id){if(!confirm('Delete this treatment plan?'))return;data.plans=data.plans.filter(function(x){return x.id!==id});save();if(currentPatientId&&$('profile').classList.contains('active'))renderProfile(currentPatientId);render();toast('Treatment plan deleted')}

function billTotal(b){return Math.max(0,(b.items||[]).reduce(function(a,it){return a+(Number(it.amount)||0)*(Number(it.qty)||1)},0)-(Number(b.discount)||0))}
function billPaid(b){return(b.payments||[]).reduce(function(a,p){return a+(Number(p.amount)||0)},0)}
function billDue(b){return Math.max(0,billTotal(b)-billPaid(b))}
function billStatus(b){if(b.status==='Cancelled')return'Cancelled';let t=billTotal(b),p=billPaid(b);return p>=t&&t>0?'Paid':p>0?'Partially paid':'Open'}
function updateBillStatus(b){b.status=billStatus(b)}
function monthOf(d){return String(d||'').slice(0,7)}
function billMonth(b){return monthOf(b.date)}
function paymentMonth(b){return (b.payments||[]).filter(function(p){return monthOf(p.date)===month()}).reduce(function(s,p){return s+(Number(p.amount)||0)},0)}
function renderDashboard(){
 let m=month(), bills=data.bills.filter(function(b){return billMonth(b)===m&&b.status!=='Cancelled'});
 let billed=bills.reduce(function(s,b){return s+billTotal(b)},0), collected=bills.reduce(function(s,b){return s+paymentMonth(b)},0);
 let due=data.bills.filter(function(b){return b.status!=='Cancelled'&&billDue(b)>0});
 let plans=data.plans.filter(function(p){return p.status==='In progress'||p.status==='Accepted'}).length;
 if($('dashBilled'))$('dashBilled').textContent='₹ '+billed.toLocaleString('en-IN');
 if($('dashCollected'))$('dashCollected').textContent='₹ '+collected.toLocaleString('en-IN');
 if($('dashDue'))$('dashDue').textContent='₹ '+data.bills.reduce(function(s,b){return s+(b.status==='Cancelled'?0:billDue(b))},0).toLocaleString('en-IN');
 if($('dashPlans'))$('dashPlans').textContent=plans;
 if($('dashDueList')) $('dashDueList').innerHTML=due.length?due.slice().sort(function(a,b){return billDue(b)-billDue(a)}).slice(0,5).map(function(b){return '<div class="row"><div><b>'+esc(b.patientName)+'</b><div class="muted">'+esc(b.id)+' · '+esc(b.title)+'</div></div><b>₹ '+billDue(b).toLocaleString('en-IN')+'</b></div>'}).join(''):'<div class="empty">No outstanding dues.</div>';
}
function renderReports(){
 let m=$('reportMonth')?($('reportMonth').value||month()):month();
 if($('reportMonth')&&!$('reportMonth').value)$('reportMonth').value=m;
 let visits=data.visits.filter(function(v){return monthOf(v.date)===m});
 let patients=data.patients.filter(function(p){return monthOf(p.createdAt)===m});
 let bills=data.bills.filter(function(b){return billMonth(b)===m&&b.status!=='Cancelled'});
 let billed=bills.reduce(function(s,b){return s+billTotal(b)},0), collected=bills.reduce(function(s,b){return s+(b.payments||[]).filter(function(pm){return monthOf(pm.date)===m}).reduce(function(a,pm){return a+(Number(pm.amount)||0)},0)},0);
 if($('repVisits'))$('repVisits').textContent=visits.length;if($('repNewPatients'))$('repNewPatients').textContent=patients.length;if($('repBilled'))$('repBilled').textContent='₹ '+billed.toLocaleString('en-IN');if($('repCollected'))$('repCollected').textContent='₹ '+collected.toLocaleString('en-IN');
 let st={Open:0,'Partially paid':0,Paid:0};bills.forEach(function(b){updateBillStatus(b);if(st[b.status]!==undefined)st[b.status]++});
 if($('repBillingStatus'))$('repBillingStatus').innerHTML=Object.keys(st).map(function(k){return '<div class="row"><span>'+k+'</span><b>'+st[k]+'</b></div>'}).join('');
 let ps={Proposed:0,Accepted:0,'In progress':0,'On hold':0,Completed:0};data.plans.filter(function(p){return monthOf(p.createdAt)===m}).forEach(function(p){if(ps[p.status]!==undefined)ps[p.status]++});
 if($('repPlanStatus'))$('repPlanStatus').innerHTML=Object.keys(ps).map(function(k){return '<div class="row"><span>'+k+'</span><b>'+ps[k]+'</b></div>'}).join('');
 let modes={};bills.forEach(function(b){(b.payments||[]).filter(function(pm){return monthOf(pm.date)===m}).forEach(function(pm){modes[pm.mode]=(modes[pm.mode]||0)+(Number(pm.amount)||0)})});
 let mk=Object.keys(modes);if($('repPaymentModes'))$('repPaymentModes').innerHTML=mk.length?mk.map(function(k){return '<div class="row"><span>'+esc(k)+'</span><b>₹ '+modes[k].toLocaleString('en-IN')+'</b></div>'}).join(''):'<div class="empty">No payments recorded this month.</div>';
 let act=[];visits.slice().reverse().slice(0,5).forEach(function(v){act.push({d:v.date,t:v.time||'',x:'Visit · '+v.patientName+' · '+(v.diagnosis||v.reason||'Clinical visit')})});bills.slice().reverse().slice(0,5).forEach(function(b){act.push({d:b.date,t:'',x:'Bill · '+b.patientName+' · ₹ '+billTotal(b).toLocaleString('en-IN')} )});act.sort(function(a,b){return (b.d+' '+b.t).localeCompare(a.d+' '+a.t)});if($('repActivity'))$('repActivity').innerHTML=act.slice(0,8).map(function(a){return '<div class="row"><div><b>'+esc(a.x)+'</b><div class="muted">'+esc(a.d)+(a.t?' · '+esc(a.t):'')+'</div></div></div>'}).join('')||'<div class="empty">No activity for this month.</div>';
}

function renderBilling(q){
 let el=$('billingList');if(!el)return;q=(q||'').trim().toLowerCase();
 let a=data.bills.filter(function(b){return !q||[b.id,b.patientName,b.patientId,b.title,(b.payments||[]).map(function(pm){return [pm.date,pm.mode,pm.note].join(' ')}).join(' ')].join(' ').toLowerCase().indexOf(q)>=0}).slice().reverse();
 let total=data.bills.reduce(function(s,b){return s+(b.status==='Cancelled'?0:billTotal(b))},0),paid=data.bills.reduce(function(s,b){return s+(b.status==='Cancelled'?0:billPaid(b))},0);
 if($('billTotalMetric'))$('billTotalMetric').textContent='₹ '+total.toLocaleString('en-IN');if($('billPaidMetric'))$('billPaidMetric').textContent='₹ '+paid.toLocaleString('en-IN');if($('billDueMetric'))$('billDueMetric').textContent='₹ '+Math.max(0,total-paid).toLocaleString('en-IN');
 if(!a.length){el.innerHTML='<div class="empty">No billing records.</div>';return}
 el.innerHTML=a.map(function(b){updateBillStatus(b);var cancelled=b.status==='Cancelled',due=billDue(b),payments=(b.payments||[]).slice().reverse();return '<div class="bill-card finance-compact-card df-context-row" data-df-type="bill" data-df-id="'+esc(b.id)+'" onclick="toggleCompactCard(event,this)" aria-expanded="false"><div class="finance-row-main"><div class="finance-primary"><b>'+esc(b.patientName||'Patient')+'</b><strong class="finance-amount">₹ '+billTotal(b).toLocaleString('en-IN')+'</strong></div><div class="finance-secondary"><span>'+esc(b.date||'No date')+' · '+esc(b.title||'Dental bill')+'</span><span class="finance-mini-balances">Paid ₹ '+billPaid(b).toLocaleString('en-IN')+' · Due ₹ '+due.toLocaleString('en-IN')+'</span></div></div><span class="bill-status finance-status '+(cancelled?'status-cancelled':due>0?'status-due':'status-paid')+'">'+esc(b.status)+'</span><button type="button" class="df-info-trigger" aria-label="Bill details" title="Bill details" onclick="event.stopPropagation();dfToggleInlineDetails(this)">ⓘ</button><div class="finance-actions compact-extra"><button class="df-action-icon" title="Bill details" aria-label="Bill details" onclick="event.stopPropagation();dfToggleInlineDetails(this.closest(\'.finance-compact-card\').querySelector(\'.df-info-trigger\'))">ⓘ</button><button class="df-action-icon" title="Edit bill" aria-label="Edit bill" onclick="event.stopPropagation();openBillForm(\''+esc(b.patientId)+'\',\''+esc(b.id)+'\')">✎</button><button class="df-action-icon" title="Print receipt" aria-label="Print receipt" onclick="event.stopPropagation();printBill(\''+esc(b.id)+'\')">▤</button>'+(due>0&&!cancelled?'<button class="df-action-icon" title="Record payment" aria-label="Record payment" onclick="event.stopPropagation();openPaymentForm(\''+esc(b.id)+'\')">＋₹</button>':'')+'</div><div class="df-inline-details" hidden></div><div class="finance-payment-preview compact-extra">'+(payments.length?'<div class="finance-subheading">Payment history</div>'+payments.map(function(pm){return '<div class="payment-compact-row" data-df-type="payment" data-df-id="'+esc(pm.id)+'"><span><b>₹ '+Number(pm.amount||0).toLocaleString('en-IN')+'</b><small>'+esc(pm.date||'No date')+' · '+esc(pm.mode||'Cash')+'</small></span><button type="button" class="df-action-icon" title="Edit payment" aria-label="Edit payment" onclick="event.stopPropagation();openPaymentEditForm(\''+esc(b.id)+'\',\''+esc(pm.id)+'\')">✎</button></div>'}).join(''):'<div class="muted">No payments recorded yet.</div>')+'</div></div>'}).join('');save();
}
function renderPatientBilling(pid){let a=data.bills.filter(function(b){return b.patientId===pid}).slice().reverse();if(!a.length)return '<div class="empty">No billing records yet.</div>';return a.map(function(b){updateBillStatus(b);let due=billDue(b),history=(b.payments||[]).map(function(pm){return '<div class="row" style="padding:6px 8px;margin-top:5px"><span>'+esc(pm.date)+' · ₹ '+Number(pm.amount).toLocaleString('en-IN')+' · '+esc(pm.mode)+'</span></div>'}).join('');return '<div class="bill-card"><div class="bill-head"><b>'+esc(b.title)+'</b><span class="bill-status">'+esc(b.status)+'</span></div><div class="muted">'+esc(b.id)+' · '+esc(b.date)+'</div><div class="bill-total">₹ '+billTotal(b).toLocaleString('en-IN')+' total · ₹ '+billPaid(b).toLocaleString('en-IN')+' paid · ₹ '+due.toLocaleString('en-IN')+' due</div>'+(b.payments&&b.payments.length?'<div class="section"><div style="display:flex;align-items:center;justify-content:space-between;gap:6px"><b class="muted">Payment history</b>'+(due>0&&b.status!=='Cancelled'?'<button type="button" class="df-action-icon" aria-label="Add payment" title="Add payment" onclick="openPaymentForm(\''+esc(b.id)+'\')"><svg viewBox="0 0 24 24"><path d="M3 7h18v12H3z"></path><path d="M3 10h18"></path><path d="M7 15h4"></path><path d="M17 3v6"></path><path d="M14 6h6"></path></svg></button>':'')+'</div>'+history+'</div>':(due>0&&b.status!=='Cancelled'?'<div class="section" style="display:flex;align-items:center;gap:6px"><span class="muted">No payments recorded yet</span><button type="button" class="df-action-icon" aria-label="Record payment" title="Record payment" onclick="openPaymentForm(\''+esc(b.id)+'\')"><svg viewBox="0 0 24 24"><path d="M3 7h18v12H3z"></path><path d="M3 10h18"></path><path d="M7 15h4"></path><path d="M17 3v6"></path><path d="M14 6h6"></path></svg></button></div>':'') )+'<div class="actions"><button class="btn ghost" onclick="openContextDetail(\'bill\',\''+esc(b.id)+'\')">Details</button><button class="btn secondary" onclick="openBillForm(\''+esc(pid)+'\',\''+esc(b.id)+'\')">Edit</button><button class="btn ghost" onclick="printBill(\''+esc(b.id)+'\')">Receipt</button>'+(due>0&&b.status!=='Cancelled'?'<button type="button" class="df-action-icon" aria-label="Record payment" title="Record payment" onclick="openPaymentForm(\''+esc(b.id)+'\')"><svg viewBox="0 0 24 24"><path d="M3 7h18v12H3z"></path><path d="M3 10h18"></path><path d="M7 15h4"></path><path d="M17 3v6"></path><path d="M14 6h6"></path></svg></button>':'')+'</div></div>'}).join('')}
let editingBillId=null,billDraftItems=[];
function fillBillTooth(){let a=[''].concat([11,12,13,14,15,16,17,18,21,22,23,24,25,26,27,28,31,32,33,34,35,36,37,38,41,42,43,44,45,46,47,48].map(String));$('billTooth').innerHTML=a.map(function(n){return '<option value="'+n+'">'+(n||'Tooth/Area')+'</option>'}).join('')}

function openBillForm(pid,id){editingBillId=id||null;let b=id?data.bills.find(function(x){return x.id===id}):null;let opts=data.patients.map(function(p){return '<option value="'+esc(p.id)+'">'+esc(p.name)+(p.phone?' — '+esc(p.phone):'')+'</option>'}).join('');$('billPatient').innerHTML=opts||'<option value="">No patients available</option>';fillBillTooth();if(pid)$('billPatient').value=pid;if(b){$('billPatient').value=b.patientId;$('billTitle').value=b.title;$('billNotes').value=b.notes;billDraftItems=JSON.parse(JSON.stringify(b.items||[]));$('billPaymentHint').textContent='Optional: record an additional payment now. Previous payments will remain in history.'}else{$('billTitle').value='';$('billNotes').value='';billDraftItems=[];$('billPaymentHint').textContent='Optional: amount received now.';$('billInitialPaymentMode').value=data.settings.defaultPaymentMode||'Cash'}$('initialPaymentFields').style.display='block';$('billInitialPayment').value='';$('billInitialPaymentMode').value=data.settings.defaultPaymentMode||'Cash';$('billPatient').onchange=null;renderBillItems();$('billFormTitle').textContent=b?'Edit Bill':'New Bill';$('billSheet').classList.add('show')}
function addBillItem(){let service=$('billService').value.trim(),amount=Number($('billAmount').value)||0,qty=Math.max(1,Number($('billQty').value)||1);if(!service){$('billService').focus();return}if(amount<=0){toast('Enter a valid service fee');$('billAmount').focus();return}billDraftItems.push({id:'BI'+Date.now().toString(36),tooth:$('billTooth').value,service:service,qty:qty,amount:amount});$('billService').value='';$('billQty').value='1';$('billAmount').value='';renderBillItems();$('billService').focus()}
function renderBillItems(){let el=$('billItems');let total=billDraftItems.reduce(function(a,it){return a+(Number(it.amount)||0)*(Number(it.qty)||1)},0);if($('billTotalDisplay'))$('billTotalDisplay').textContent='₹ '+total.toLocaleString('en-IN');if(!billDraftItems.length){el.innerHTML='<div class="muted">No services added yet.</div>';return}el.innerHTML=billDraftItems.map(function(it,i){return '<div class="wf-bill-line"><span class="wf-bill-name">'+esc(it.tooth?it.tooth+' · ':'')+esc(it.service)+' × '+(Number(it.qty)||1)+'</span><span class="wf-bill-fee">₹ '+((Number(it.amount)||0)*(Number(it.qty)||1)).toLocaleString('en-IN')+'</span><button type="button" aria-label="Remove '+esc(it.service)+'" title="Remove item" onclick="billDraftItems.splice('+i+',1);renderBillItems()">×</button></div>'}).join('')}
function saveBill(){let p=patient($('billPatient').value);if(!p){alert('Please select a patient.');return}if(!billDraftItems.length){alert('Add at least one bill item.');return}let b=editingBillId?data.bills.find(function(x){return x.id===editingBillId}):null;let isNew=!b;if(!b){b={id:'B'+Date.now().toString(36),patientId:p.id,patientName:p.name,date:day(),title:'Dental bill',status:'Open',notes:'',items:[],payments:[]}}let newItems=JSON.parse(JSON.stringify(billDraftItems));let newTotal=newItems.reduce(function(a,it){return a+(Number(it.amount)||0)*(Number(it.qty)||1)},0);if(b&&billPaid(b)>newTotal){alert('Bill total cannot be lower than payments already recorded (₹ '+billPaid(b).toLocaleString('en-IN')+').');return}let firstPaid=Number($('billInitialPayment').value)||0,alreadyPaid=b?billPaid(b):0,remainingAfterItems=Math.max(0,newTotal-alreadyPaid);if(!isFinite(firstPaid)||firstPaid<0||firstPaid>remainingAfterItems){alert('Enter a valid additional payment between ₹0 and the remaining due (₹ '+remainingAfterItems.toLocaleString('en-IN')+').');return}if(b){b.changeHistory=Array.isArray(b.changeHistory)?b.changeHistory:[];b.changeHistory.push({changedAt:new Date().toISOString(),reason:'Bill details edited',previous:{title:b.title||'',notes:b.notes||'',items:JSON.parse(JSON.stringify(b.items||[])),total:billTotal(b)}})}var billBeforeEdit=isNew?null:JSON.stringify(b);Object.assign(b,{patientId:p.id,patientName:p.name,title:$('billTitle').value.trim()||'Dental bill',notes:$('billNotes').value.trim(),items:newItems,updatedAt:new Date().toISOString()});b.payments=b.payments||[];if(firstPaid>0){b.payments.push({id:'PM'+Date.now().toString(36),date:day(),amount:firstPaid,mode:$('billInitialPaymentMode').value||'Cash',note:isNew?'Payment received while creating bill':'Additional payment received while editing bill'})}if(isNew)data.bills.push(b);updateBillStatus(b);if(!save()){if(isNew)data.bills=data.bills.filter(function(x){return x.id!==b.id});else if(billBeforeEdit)Object.assign(b,JSON.parse(billBeforeEdit));alert('Bill could not be saved to device storage. Please export a backup and retry.');return}closeSheet('billSheet');editingBillId=null;billDraftItems=[];currentPatientId=p.id;switchView('profile');toast('Bill saved')}
let editingPaymentBillId=null,editingPaymentId=null;
function openPaymentForm(id){editingPaymentId=null;let b=data.bills.find(function(x){return x.id===id});if(!b)return;let due=billDue(b);if(due<=0){toast('No due balance');return}editingPaymentBillId=id;$('paymentInfo').innerHTML='<b>'+esc(b.patientName)+'</b><div class="muted">'+esc(b.id)+' · '+esc(b.title)+'</div><div class="bill-total">Due ₹ '+due.toLocaleString('en-IN')+'</div>';$('paymentAmount').value=String(due);$('paymentMode').value=data.settings.defaultPaymentMode||'UPI';$('paymentDate').value=day();$('paymentNote').value='';$('paymentSheet').classList.add('show');$('paymentAmount').focus()}
function openPaymentEditForm(billId,paymentId){let b=data.bills.find(function(x){return x.id===billId}),pm=b&&(b.payments||[]).find(function(x){return x.id===paymentId});if(!b||!pm)return;editingPaymentBillId=billId;editingPaymentId=paymentId;$('paymentInfo').innerHTML='<b>Edit payment</b><div class="muted">'+esc(b.patientName)+' · '+esc(b.id)+'</div><div class="bill-total">Current payment ₹ '+Number(pm.amount||0).toLocaleString('en-IN')+'</div>';$('paymentAmount').value=String(pm.amount||'');$('paymentMode').value=pm.mode||'Cash';$('paymentDate').value=pm.date||day();$('paymentNote').value=pm.note||'';$('paymentSheet').classList.add('show');$('paymentAmount').focus()}
function savePayment(){let b=data.bills.find(function(x){return x.id===editingPaymentBillId});if(!b)return;let paymentBeforeEdit=JSON.stringify(b);let old=editingPaymentId?(b.payments||[]).find(function(x){return x.id===editingPaymentId}):null,due=billDue(b)+(old?Number(old.amount||0):0),amount=Number($('paymentAmount').value);if(!isFinite(amount)||amount<=0||amount>due){alert('Enter a valid amount up to the available balance.');return}b.payments=b.payments||[];if(old){old.correctionHistory=Array.isArray(old.correctionHistory)?old.correctionHistory:[];old.correctionHistory.push({correctedAt:new Date().toISOString(),previous:{date:old.date||'',amount:Number(old.amount||0),mode:old.mode||'',note:old.note||''},reason:'Edited through DentalFlow payment form'});old.date=$('paymentDate').value||day();old.amount=amount;old.mode=$('paymentMode').value;old.note=$('paymentNote').value.trim();old.updatedAt=new Date().toISOString()}else b.payments.push({id:'PM'+Date.now().toString(36),date:$('paymentDate').value||day(),amount:amount,mode:$('paymentMode').value,note:$('paymentNote').value.trim(),createdAt:new Date().toISOString()});updateBillStatus(b);if(!save()){var restoredBill=JSON.parse(paymentBeforeEdit);Object.keys(b).forEach(function(k){delete b[k]});Object.assign(b,restoredBill);alert('Payment could not be saved to device storage. The previous payment values were restored in memory. Please export a backup and retry.');return}closeSheet('paymentSheet');editingPaymentBillId=null;editingPaymentId=null;render();if(currentPatientId&&$('profile').classList.contains('active'))renderProfile(currentPatientId);toast(old?'Payment updated':'Payment recorded')}
function printBill(id){let b=data.bills.find(function(x){return x.id===id});if(!b)return;let w=window.open('','_blank');if(!w){alert('Allow pop-ups to print the receipt.');return}let rows=(b.items||[]).map(function(it){return '<tr><td>'+esc(it.tooth||'')+'</td><td>'+esc(it.service)+'</td><td>'+it.qty+'</td><td>₹ '+(it.amount*it.qty).toLocaleString('en-IN')+'</td></tr>'}).join('');let clinicHead='<h2>'+esc(data.settings.clinicName||'Dental Clinic')+'</h2>'+(data.settings.showDoctorOnReceipt&&data.settings.doctorName?'<div>'+esc(data.settings.doctorName)+'</div>':'')+(data.settings.showContactOnReceipt&&data.settings.clinicPhone?'<div>'+esc(data.settings.clinicPhone)+'</div>':'')+(data.settings.showContactOnReceipt&&data.settings.clinicAddress?'<div>'+esc(data.settings.clinicAddress)+'</div>':'')+(data.settings.registrationNo?'<div>'+esc(data.settings.registrationNo)+'</div>':'');let html='<!doctype html><html><head><meta charset="utf-8"><title>'+esc(b.id)+'</title><style>body{font-family:Arial,sans-serif;padding:24px;max-width:700px;margin:auto}table{width:100%;border-collapse:collapse}th,td{border-bottom:1px solid #ddd;padding:8px;text-align:left}.total{text-align:right;font-weight:bold;margin-top:15px}</style></head><body>'+clinicHead+'<hr><h3>Dental Receipt</h3><p><b>Patient:</b> '+esc(b.patientName)+'<br><b>Bill:</b> '+esc(b.id)+'<br><b>Date:</b> '+esc(b.date)+'</p><table><tr><th>Tooth</th><th>Service</th><th>Qty</th><th>Amount</th></tr>'+rows+'</table><p class="total">Total: ₹ '+billTotal(b).toLocaleString('en-IN')+'<br>Paid: ₹ '+billPaid(b).toLocaleString('en-IN')+'<br>Due: ₹ '+billDue(b).toLocaleString('en-IN')+'</p><p>Payment mode(s): '+esc((b.payments||[]).map(function(x){return x.mode}).join(', ')||'—')+'</p></body></body></html>';w.document.write(html);w.document.close();w.focus();w.print()}

function templatesFor(cat){return(data.templates||[]).filter(function(t){return t.category===cat})}
function insertTemplate(cat,id){let t=(data.templates||[]).find(function(x){return x.id===id});if(!t)return;let map={exam:'visitExam',dx:'visitDiagnosis',tx:'visitTreatment',advice:'visitAdvice',rx:'visitPrescription'};let area=$(map[cat]);if(!area)return;area.value=area.value.trim()?area.value.trim()+'\n'+t.text:t.text;area.focus();}
function renderTemplateBar(cat,elId){let el=$(elId);if(!el)return;let a=templatesFor(cat);el.innerHTML=a.map(function(t){return '<button type="button" onclick="insertTemplate(\''+esc(cat)+'\',\''+esc(t.id)+'\')">'+esc(t.name)+'</button>'}).join('')}
function renderVisitTemplateBars(){renderTemplateBar('exam','examTemplates');renderTemplateBar('dx','dxTemplates');renderTemplateBar('tx','txTemplates');renderTemplateBar('advice','adviceTemplates');renderTemplateBar('rx','rxTemplates')}
function renderTemplateManager(){let el=$('templateManager');if(!el)return;let cats=[['exam','Examination'],['dx','Diagnosis'],['tx','Treatment'],['advice','Advice'],['rx','Prescription']];el.innerHTML=cats.map(function(c){let a=templatesFor(c[0]);return '<div class="section"><b>'+c[1]+'</b><div class="template-list">'+(a.length?a.map(function(t){return '<div class="template-card"><b>'+esc(t.name)+'</b><pre>'+esc(t.text)+'</pre><div class="actions"><button class="btn secondary" onclick="editTemplate(\''+esc(t.id)+'\')">Edit</button><button class="btn danger" onclick="deleteTemplate(\''+esc(t.id)+'\')">Delete</button></div></div>'}).join(''):'<div class="muted">No templates.</div>')+'</div></div>'}).join('')}
function openTemplateEditor(id){let t=id?(data.templates||[]).find(function(x){return x.id===id}):null;let el=$('templateManager');if(!el)return;let form=document.createElement('div');form.className='template-form';form.innerHTML='<b>'+(t?'Edit template':'New template')+'</b><div><select id="tplCat"><option value="exam">Examination</option><option value="dx">Diagnosis</option><option value="tx">Treatment</option><option value="advice">Advice</option><option value="rx">Prescription</option></select></div><input id="tplName" placeholder="Template name"><textarea id="tplText" placeholder="Reusable text…"></textarea><div class="actions"><button class="btn" onclick="saveTemplate(\''+(t?esc(t.id):'')+'\')">Save template</button><button class="btn ghost" onclick="renderTemplateManager()">Cancel</button></div>';el.prepend(form);if(t){$('tplCat').value=t.category;$('tplName').value=t.name;$('tplText').value=t.text}}
function editTemplate(id){openTemplateEditor(id)}
function saveTemplate(id){let name=$('tplName').value.trim(),text=$('tplText').value.trim(),cat=$('tplCat').value;if(!name||!text){alert('Enter a template name and text.');return}if(id){let t=data.templates.find(function(x){return x.id===id});if(t)Object.assign(t,{name:name,text:text,category:cat})}else data.templates.push({id:'T'+Date.now().toString(36),category:cat,name:name,text:text});save();renderTemplateManager();toast('Template saved')}
function deleteTemplate(id){if(!confirm('Delete this template?'))return;data.templates=data.templates.filter(function(x){return x.id!==id});save();renderTemplateManager();toast('Template deleted')}

function detailEscape(v){return esc(v==null||v===''?'—':v)}
function detailField(label,value){if(value==null||String(value).trim()==='')return '';return '<div class="detail-block"><div class="detail-label">'+esc(label)+'</div><div class="detail-value">'+esc(String(value))+'</div></div>'}
function startContextWorkflow(action,sourceType,sourceId,pid){
 var patientId=pid||currentPatientId||'';
 var source=null;
 if(sourceType==='visit')source=data.visits.find(function(z){return z.id===sourceId&&z.patientId===patientId});
 else if(sourceType==='plan')source=data.plans.find(function(z){return z.id===sourceId&&z.patientId===patientId});
 else if(sourceType==='bill')source=data.bills.find(function(z){return z.id===sourceId&&z.patientId===patientId});
 else if(sourceType==='appointment')source=data.appointments.find(function(z){return z.id===sourceId&&z.patientId===patientId});
 if(!patient(patientId)){toast('Patient record not found');return}
 closeSheet('contextDetailSheet');closeSheet('patientContextSheet');currentPatientId=patientId;
 setTimeout(function(){
  if(action==='visit'){
   openVisitForm(patientId);
   if(sourceType==='appointment'&&source){$('visitChief').value=source.reason||'';$('visitNext').value=source.date&&source.date>=day()?source.date:'';}
  }else if(action==='plan'){
   openPlanForm(patientId);
   
  }else if(action==='bill'){
   openBillForm(patientId);
   
   
   if(sourceType==='appointment'&&source)$('billTitle').value=source.reason||'';
  }else if(action==='reminder'){
   openReminderForm('',patientId);
   
   
   if(sourceType==='bill'&&source){$('remType').value='Payment';$('remNote').value='Payment follow-up for bill '+source.id+(billDue(source)>0?' · Due ₹ '+billDue(source).toLocaleString('en-IN'):'');}
   if(sourceType==='appointment'&&source){$('remType').value='Follow-up';$('remNote').value='Follow-up after appointment on '+(source.date||'');}
  }
 },40);
}
function openContextDetail(type,id){
 var x=null,title='',body='',pid='',actions='';
 if(type==='visit'){x=data.visits.find(function(v){return v.id===id});if(!x)return;pid=x.patientId;title='Clinical Visit Details';body=detailField('Patient',x.patientName||((patient(pid)||{}).name)||pid)+detailField('Date / time',(x.date||'')+(x.time?' · '+x.time:''))+detailField('Chief complaint',x.chiefComplaint||x.reason)+detailField('History',x.history)+detailField('Examination',x.examination)+detailField('Diagnosis',x.diagnosis)+detailField('Treatment done',x.treatmentDone)+detailField('Advice',x.advice)+detailField('Prescription',x.prescription)+detailField('Next visit',x.nextVisit)+detailField('Tooth / area',(x.teeth||[]).map(function(t){return t.no+' · '+t.status}).join('\n'));actions='<button class="btn secondary" onclick="startContextWorkflow(\'plan\',\'visit\',\''+esc(x.id)+'\',\''+esc(pid)+'\')">+ Treatment Plan</button><button class="btn secondary" onclick="startContextWorkflow(\'bill\',\'visit\',\''+esc(x.id)+'\',\''+esc(pid)+'\')">+ Bill</button><button class="btn ghost" onclick="openFollowupForm(\'\',\''+esc(pid)+'\',\''+esc(x.id)+'\')">+ Follow-up</button><button class="btn secondary" onclick="openProfile(\''+esc(pid)+'\');closeSheet(\'contextDetailSheet\')">Patient profile</button>';
 }else if(type==='plan'){x=data.plans.find(function(v){return v.id===id});if(!x)return;pid=x.patientId;title='Treatment Plan Details';var items=(x.items||[]).map(function(i){return (i.tooth||'—')+' · '+(i.procedure||'Treatment')+' · '+(i.status||'')+(i.estimate?' · ₹ '+Number(i.estimate).toLocaleString('en-IN'):'')+(i.notes?'\n'+i.notes:'')}).join('\n\n');body=detailField('Patient',(patient(pid)||{}).name||pid)+detailField('Plan',x.title)+detailField('Status',x.status)+detailField('Procedures',items)+detailField('Notes',x.notes)+detailField('Estimated total','₹ '+planTotal(x).toLocaleString('en-IN'));actions='<button class="btn secondary" onclick="startContextWorkflow(\'bill\',\'plan\',\''+esc(x.id)+'\',\''+esc(pid)+'\')">+ Bill</button><button class="btn ghost" onclick="startContextWorkflow(\'reminder\',\'plan\',\''+esc(x.id)+'\',\''+esc(pid)+'\')">+ Follow-up</button><button class="btn" onclick="closeSheet(\'contextDetailSheet\');openPlanForm(\''+esc(pid)+'\',\''+esc(x.id)+'\')">Edit plan</button><button class="btn secondary" onclick="openProfile(\''+esc(pid)+'\');closeSheet(\'contextDetailSheet\')">Patient profile</button>';
 }else if(type==='bill'){x=data.bills.find(function(v){return v.id===id});if(!x)return;pid=x.patientId;title='Bill & Payment Details';var pays=(x.payments||[]).map(function(a){return (a.date||'')+' · ₹ '+Number(a.amount||0).toLocaleString('en-IN')+' · '+(a.mode||'')}).join('\n');body=detailField('Patient',x.patientName||((patient(pid)||{}).name)||pid)+detailField('Invoice',x.id)+detailField('Date',x.date)+detailField('Title',x.title)+detailField('Status',x.status)+detailField('Items',(x.items||[]).map(function(i){return (i.service||'Service')+(i.tooth?' · '+i.tooth:'')+' · '+(i.qty||1)+' × ₹ '+Number(i.amount||0).toLocaleString('en-IN')}).join('\n'))+detailField('Total','₹ '+billTotal(x).toLocaleString('en-IN'))+detailField('Paid','₹ '+billPaid(x).toLocaleString('en-IN'))+detailField('Due','₹ '+billDue(x).toLocaleString('en-IN'))+detailField('Payments',pays)+detailField('Notes',x.notes);actions='<button class="btn ghost" onclick="startContextWorkflow(\'reminder\',\'bill\',\''+esc(x.id)+'\',\''+esc(pid)+'\')">Payment reminder</button><button class="btn" onclick="closeSheet(\'contextDetailSheet\');openBillForm(\''+esc(pid)+'\',\''+esc(x.id)+'\')">Edit bill</button>'+(billDue(x)>0&&x.status!=='Cancelled'?'<button class="btn secondary" onclick="closeSheet(\'contextDetailSheet\');openPaymentForm(\''+esc(x.id)+'\')">+ Payment</button>':'')+'<button class="btn ghost" onclick="printBill(\''+esc(x.id)+'\')">Receipt</button><button class="btn secondary" onclick="openProfile(\''+esc(pid)+'\');closeSheet(\'contextDetailSheet\')">Patient profile</button>';
 }else if(type==='appointment'){x=data.appointments.find(function(v){return v.id===id});if(!x)return;pid=x.patientId;title='Appointment Details';body=detailField('Patient',x.patientName||((patient(pid)||{}).name)||pid)+detailField('Date / time',(x.date||'')+(x.time?' · '+x.time:''))+detailField('Reason / treatment',x.reason)+detailField('Status',x.status)+detailField('Notes',x.notes);actions='<button class="btn secondary" onclick="startContextWorkflow(\'visit\',\'appointment\',\''+esc(x.id)+'\',\''+esc(pid)+'\')">Start Clinical Visit</button><button class="btn ghost" onclick="startContextWorkflow(\'reminder\',\'appointment\',\''+esc(x.id)+'\',\''+esc(pid)+'\')">+ Follow-up</button><button class="btn" onclick="closeSheet(\'contextDetailSheet\');openAppointmentForm(\''+esc(x.id)+'\')">Edit appointment</button><button class="btn secondary" onclick="openProfile(\''+esc(pid)+'\');closeSheet(\'contextDetailSheet\')">Patient profile</button>';
 }else if(type==='reminder'){x=data.reminders.find(function(v){return v.id===id});if(!x)return;pid=x.patientId;title='Follow-up / Reminder Details';body=detailField('Patient',x.patientName||((patient(pid)||{}).name)||pid)+detailField('Due date',x.dueDate+(x.dueTime?' · '+x.dueTime:''))+detailField('Type',x.type)+detailField('Status',x.status)+detailField('Note',x.note);actions='<button class="btn" onclick="closeSheet(\'contextDetailSheet\');openReminderForm(\''+esc(x.id)+'\')">Edit reminder</button>'+(x.status!=='Done'?'<button class="btn secondary" onclick="closeSheet(\'contextDetailSheet\');setReminderStatus(\''+esc(x.id)+'\',\'Done\')">Mark done</button>':'')+'<button class="btn secondary" onclick="openProfile(\''+esc(pid)+'\');closeSheet(\'contextDetailSheet\')">Patient profile</button>';
 }else if(type==='record'){x=data.records.find(function(v){return v.id===id});if(!x)return;pid=x.patientId;title='Patient Record Details';body=detailField('Patient',(patient(pid)||{}).name||pid)+detailField('Type',x.type)+detailField('Date',x.date)+detailField('Title',x.title)+detailField('Details',x.details);actions='<button class="btn" onclick="closeSheet(\'contextDetailSheet\');openRecordForm(\''+esc(x.id)+'\')">Edit record</button><button class="btn secondary" onclick="openProfile(\''+esc(pid)+'\');closeSheet(\'contextDetailSheet\')">Patient profile</button>';
 }else{return}
 $('contextDetailTitle').textContent=title;$('contextDetailContent').innerHTML=body+'<div class="detail-actions">'+actions+'<button class="btn ghost" onclick="closeSheet(\'contextDetailSheet\')">Close</button></div>';openSheet('contextDetailSheet');
}
function openSheet(id){$(id).classList.add('show')}
function closeSheet(id){$(id).classList.remove('show')}document.querySelectorAll('.overlay').forEach(function(o){o.addEventListener('click',function(e){if(e.target===o)o.classList.remove('show')})});
function toggleMenu(show){document.getElementById('menuOverlay').classList.toggle('show',!!show)}function menuGo(id){toggleMenu(false);switchView(id)}
function contextFabForView(){
  var active=document.querySelector('.view.active');
  var id=active?active.id:'home';
  if(id==='home')return {label:'Open patient workflow',run:function(){openUnifiedWorkflow(currentPatientId||'')}};
  if(id==='patients')return {label:'Add patient',run:function(){openPatientForm()}};
  if(id==='profile'&&currentPatientId)return {label:'Continue patient workflow',run:function(){openUnifiedWorkflow(currentPatientId)}};
  if(id==='visits')return {label:'New clinical visit',run:function(){openVisitForm(currentPatientId||'')}};
  if(id==='appointments'){
    var root=document.querySelector('.chairside-module[data-module="schedule"]');
    var pane=root&&root.dataset.activePane||'appointmentsPane';
    if(pane==='queuePane')return {label:'Add walk-in to queue',run:function(){openWalkInQueueForm()}};
    return {label:'New appointment',run:function(){openAppointmentForm('',currentPatientId||'')}};
  }
  if(id==='reminders'){
    var root=document.querySelector('.chairside-module[data-module="followups"]');
    var pane=root&&root.dataset.activePane||'followupsPane';
    if(pane==='remindersPane')return null; // reminders are generated from their source appointment/follow-up
    return {label:'New follow-up',run:function(){openFollowupForm('',currentPatientId||'')}};
  }
  if(id==='billing')return {label:'New bill',run:function(){openBillForm(currentPatientId||'')}};
  if(id==='records')return {label:'New patient record',run:function(){openRecordForm('',currentPatientId||'')}};
  return null;
}
function renderFab(){
  var wrap=$('fabWrap'),menu=$('fabMenu'),button=$('fabMain');if(!wrap||!menu||!button)return;
  var action=contextFabForView();wrap.classList.remove('open');menu.innerHTML='';
  if(!action){wrap.style.display='none';button.onclick=null;return}
  wrap.style.display='flex';button.setAttribute('aria-label',action.label);button.setAttribute('title',action.label);button.onclick=function(){try{action.run()}catch(e){console.error('DentalFlow contextual FAB error',e)}};
}
function toggleFab(){var action=contextFabForView();if(action)action.run()}
/* Finance FAB direct route: open the New Bill form without relying on a menu toggle. */
document.addEventListener('click',function(e){var b=e.target&&e.target.closest?e.target.closest('#fabMain'):null;if(!b)return;var active=document.querySelector('.view.active');if(active&&active.id==='billing'){e.preventDefault();e.stopImmediatePropagation();try{openBillForm(currentPatientId||'')}catch(err){console.error('Finance FAB could not open bill form',err);toast('Unable to open bill form. Please retry.')}}},true);
function runFabAction(){var action=contextFabForView();if(action)action.run()}
document.addEventListener('click',function(e){var w=$('fabWrap');if(w&&w.classList.contains('open')&&!w.contains(e.target))w.classList.remove('open')});
document.addEventListener('keydown',function(e){if(e.key==='Escape'){toggleMenu(false);document.querySelectorAll('.overlay.show').forEach(function(x){x.classList.remove('show')})}});function switchView(id){document.querySelectorAll('.view').forEach(function(x){x.classList.toggle('active',x.id===id)});document.querySelectorAll('.nav').forEach(function(x){x.classList.toggle('active',x.getAttribute('data-v')===id)});try{render();renderFab();if(id==='more')document.querySelectorAll('.nav').forEach(function(x){x.classList.toggle('active',x.getAttribute('data-v')==='more')})}catch(e){console.error('DentalFlow navigation error',e);$('bootError').classList.add('show')}}function showView(id){switchView(id)}document.querySelectorAll('.nav').forEach(function(b){b.addEventListener('click',function(){switchView(b.getAttribute('data-v'))})});
function backup(){try{var payload=snapshotPayload(),file={app:'DentalFlow',formatVersion:1,appVersion:'7.8.52',exportedAt:new Date().toISOString(),counts:backupCounts(payload),data:payload};var a=document.createElement('a');var u=URL.createObjectURL(new Blob([JSON.stringify(file,null,2)],{type:'application/json'}));a.href=u;a.download='DentalFlow-backup-'+day()+'.json';a.click();setTimeout(function(){URL.revokeObjectURL(u)},1000);toast('JSON backup exported')}catch(e){console.error(e);alert('Backup export failed. Please try again.')}}function downloadBackupFile(){backup()}
