function saveAllSettings(){data.settings.clinicName=$('clinicName').value.trim()||'Dental Clinic';data.settings.doctorName=$('doctorName').value.trim();data.settings.clinicPhone=$('clinicPhone').value.trim();data.settings.clinicAddress=$('clinicAddress').value.trim();data.settings.registrationNo=$('registrationNo').value.trim();data.settings.defaultPaymentMode=$('defaultPaymentMode').value;data.settings.defaultAppointmentStatus=$('defaultAppointmentStatus').value;data.settings.defaultReminderType=$('defaultReminderType').value;data.settings.showDoctorOnReceipt=$('showDoctorOnReceipt').checked;data.settings.showContactOnReceipt=$('showContactOnReceipt').checked;data.settings.compactMode=$('compactMode').checked;save();render();if($('settingsSaved'))$('settingsSaved').textContent='Saved ✓';toast('Settings saved')}function resetPreferences(){if(!confirm('Reset only DentalFlow preferences to defaults? Patient and clinical data will not be changed.'))return;let d=blank().settings;data.settings={clinicName:data.settings.clinicName||d.clinicName,doctorName:data.settings.doctorName||d.doctorName,clinicPhone:data.settings.clinicPhone||'',clinicAddress:data.settings.clinicAddress||'',registrationNo:data.settings.registrationNo||'',defaultPaymentMode:d.defaultPaymentMode,defaultAppointmentStatus:d.defaultAppointmentStatus,defaultReminderType:d.defaultReminderType,showDoctorOnReceipt:d.showDoctorOnReceipt,showContactOnReceipt:d.showContactOnReceipt,compactMode:d.compactMode};save();render();toast('Preferences reset')}function saveSettings(){saveAllSettings()}$('clinicName').addEventListener('change',saveSettings);$('doctorName').addEventListener('change',saveSettings)
