function exportRecoveryData(){try{var raw=localStorage.getItem(KEY);if(raw===null){alert('No saved DentalFlow data was found in the primary storage key. Do not reset the app.');return}var isJson=true;try{JSON.parse(raw)}catch(e){isJson=false}var blob=new Blob([raw],{type:isJson?'application/json':'text/plain'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='DentalFlow-recovery-'+new Date().toISOString().slice(0,10)+(isJson?'.json':'.txt');document.body.appendChild(a);a.click();a.remove();setTimeout(function(){URL.revokeObjectURL(url)},1500);alert('Stored data export started. Keep this file safe. This is a raw recovery copy; if the data is damaged it may need manual review before import.')}catch(e){console.error('Recovery export failed',e);alert('Could not export stored data. Do not clear site data; try again and preserve the current app storage.')}}function boot(){try{load();if(window.__dfLoadError){$('bootErrorText').textContent='DentalFlow could not safely read the saved data. The app has not saved an empty replacement. Export the stored data before trying again.';$('bootError').classList.add('show');return}render();$('bootError').classList.remove('show')}catch(e){console.error('DentalFlow boot error',e);$('bootErrorText').textContent='DentalFlow could not finish loading. Your saved data has not been intentionally reset. Export stored data before retrying.';$('bootError').classList.add('show')}}document.addEventListener('DOMContentLoaded',function(){initWorkflowDraftRecovery();initWorkflowBilling()},{once:true});if(document.readyState!=='loading')initWorkflowDraftRecovery();window.addEventListener('pageshow',boot);if('serviceWorker' in navigator&&location.protocol.indexOf('http')===0)window.addEventListener('load',async function(){try{let r=await navigator.serviceWorker.register('./sw.js',{updateViaCache:'none'});await r.update()}catch(e){console.warn('SW',e)}});if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',boot,{once:true});else boot();
