function recordById(id){return data.records.find(function(r){return r.id===id})}
function populateRecordPatients(selected){var el=$('recPatient');if(!el)return;el.innerHTML='<option value="">Select patient</option>'+data.patients.slice().sort(function(a,b){return a.name.localeCompare(b.name)}).map(function(p){return '<option value="'+esc(p.id)+'" '+(p.id===selected?'selected':'')+'>'+esc(p.name)+' · '+esc(p.phone||p.id)+'</option>'}).join('')}
function openRecordForm(id,patientId){if(!data.patients.length){alert('Add a patient first.');return}var r=id?recordById(id):null;populateRecordPatients(r?r.patientId:patientId||currentPatientId||'');$('recordFormTitle').textContent=r?'Edit Patient Record':'New Patient Record';$('recType').value=r?(r.type||'Other'):'Medical history';$('recDate').value=r?(r.date||day()):day();$('recTitle').value=r?(r.title||''):'';$('recDetails').value=r?(r.details||''):'';$('recordSheet').dataset.editId=r?r.id:'';openSheet('recordSheet')}
function saveRecord(){var pid=$('recPatient').value,title=$('recTitle').value.trim();if(!pid||!title){alert('Select a patient and enter a title.');return}var id=$('recordSheet').dataset.editId,r=id?recordById(id):null;if(!r){r={id:'R'+Date.now().toString(36),createdAt:new Date().toISOString()};data.records.push(r)}Object.assign(r,{patientId:pid,type:$('recType').value,date:$('recDate').value||day(),title:title,details:$('recDetails').value.trim()});save();closeSheet('recordSheet');$('recordSheet').dataset.editId='';render();toast('Record saved')}
function deleteRecord(id){if(!confirm('Delete this patient record?'))return;data.records=data.records.filter(function(r){return r.id!==id});save();render();toast('Record deleted')}
function renderRecords(q){var el=$('recordList');if(!el)return;q=(q||'').trim().toLowerCase();var arr=data.records.slice().sort(function(a,b){return String(b.date||'').localeCompare(String(a.date||''))});if(q)arr=arr.filter(function(r){var p=patient(r.patientId);return [r.title,r.type,r.details,p?p.name:'',p?p.phone:'',r.patientId].join(' ').toLowerCase().indexOf(q)>=0});if(!arr.length){el.innerHTML='<div class="empty">No patient records found.</div>';return}el.innerHTML=arr.map(function(r){var p=patient(r.patientId);return '<div class="card record-card"><div class="record-top"><div><b>'+esc(r.title)+'</b><div class="muted">'+esc(r.date||'—')+' · '+esc(r.type)+'</div><div class="muted">Patient: '+esc(p?p.name:r.patientId)+'</div></div></div>'+(r.details?'<p>'+esc(r.details)+'</p>':'')+'<div class="actions"><button class="btn ghost" onclick="openContextDetail(\'record\',\''+esc(r.id)+'\')">Details</button><button class="btn secondary" onclick="openRecordForm(\''+esc(r.id)+'\')">Edit</button><button class="btn danger" onclick="deleteRecord(\''+esc(r.id)+'\')">Delete</button><button class="btn ghost" onclick="openProfile(\''+esc(r.patientId)+'\')">Patient</button></div></div>'}).join('')}
/* V7.8.19: shared chairside date grouping, tab state and swipe handling. */
function selectChairsideTab(moduleId,paneId){var root=document.querySelector('.chairside-module[data-module="'+moduleId+'"]');if(!root)return;root.querySelectorAll('.chairside-tab').forEach(function(b){var on=b.getAttribute('data-target')===paneId;b.classList.toggle('active',on);b.setAttribute('aria-selected',on?'true':'false')});root.querySelectorAll('.chairside-pane').forEach(function(p){p.classList.toggle('active',p.id===paneId)});root.dataset.activePane=paneId}
function initChairsideSwipe(){document.querySelectorAll('.chairside-module').forEach(function(root){if(root.dataset.swipeReady)return;root.dataset.swipeReady='1';var sx=0,sy=0;root.addEventListener('touchstart',function(e){if(!e.touches||e.touches.length!==1)return;sx=e.touches[0].clientX;sy=e.touches[0].clientY},{passive:true});root.addEventListener('touchend',function(e){if(!e.changedTouches||e.changedTouches.length!==1)return;var dx=e.changedTouches[0].clientX-sx,dy=e.changedTouches[0].clientY-sy;if(Math.abs(dx)<65||Math.abs(dx)<Math.abs(dy)*1.25)return;var panes=Array.from(root.querySelectorAll('.chairside-pane')),active=panes.findIndex(function(p){return p.classList.contains('active')});var next=dx<0?Math.min(panes.length-1,active+1):Math.max(0,active-1);if(next!==active)selectChairsideTab(root.dataset.module,panes[next].id)},{passive:true})})}
function chairsideDateLabel(date){if(!date)return 'No date';var today=day(),tomorrow=new Date(today+'T12:00:00');tomorrow.setDate(tomorrow.getDate()+1);var tm=tomorrow.getFullYear()+'-'+String(tomorrow.getMonth()+1).padStart(2,'0')+'-'+String(tomorrow.getDate()).padStart(2,'0');if(date<today)return 'Overdue';if(date===today)return 'Today';if(date===tm)return 'Tomorrow';return date}
function toggleCompactCard(ev,el){if(!el)return;if(ev&&ev.target&&ev.target.closest('button,a,input,select,textarea')&&!ev.target.closest('.compact-expand-hint'))return;el.classList.toggle('expanded');var hint=el.querySelector('.compact-expand-hint');if(hint){hint.textContent=el.classList.contains('expanded')?'×':'⋮';hint.setAttribute('aria-label',el.classList.contains('expanded')?'Hide actions':'Show actions')}}
var dateGroupOpenState=window.__dfDateGroupOpenState||(window.__dfDateGroupOpenState={});
function collapsibleDateGroup(label,count,body,defaultOpen,groupKey,kind){var key=groupKey||label,open=Object.prototype.hasOwnProperty.call(dateGroupOpenState,key)?dateGroupOpenState[key]:!!defaultOpen;return '<details class="date-group date-group-'+(kind|| (label==='Today'?'today':label==='Overdue'?'overdue':'upcoming'))+'" data-date-group-key="'+esc(key)+'" '+(open?'open':'')+'><summary class="date-group-title"><span>'+esc(label)+'</span><small>'+count+' item'+(count===1?'':'s')+'</small></summary><div class="date-group-body">'+body+'</div></details>'}
document.addEventListener('toggle',function(e){var d=e.target;if(d&&d.matches&&d.matches('details[data-date-group-key]'))dateGroupOpenState[d.getAttribute('data-date-group-key')]=d.open},true);
function groupChairsideRows(rows,dateKey,timeKey,renderRow){if(!rows.length)return '<div class="empty">Nothing here yet.</div>';var groups={};rows.forEach(function(row){var d=row[dateKey]||'';var key=chairsideDateLabel(d);if(!groups[key])groups[key]=[];groups[key].push(row)});var order=['Overdue','Today','Tomorrow'];Object.keys(groups).forEach(function(k){if(order.indexOf(k)<0)order.push(k)});return order.filter(function(k){return groups[k]}).map(function(k){groups[k].sort(function(a,b){return String(a[timeKey]||'99:99').localeCompare(String(b[timeKey]||'99:99'))});var body=groups[k].map(renderRow).join(''),open=k==='Today'||k==='Overdue';return collapsibleDateGroup(k,groups[k].length,body,open,'date:'+dateKey+':'+k,k==='Today'?'today':k==='Overdue'?'overdue':'upcoming')}).join('')}
function chairsideAction(label,icon,fn,extra){return '<button class="chairside-icon-action '+(extra||'')+'" aria-label="'+esc(label)+'" title="'+esc(label)+'" onclick="'+fn+'"><svg viewBox="0 0 24 24" aria-hidden="true">'+icon+'</svg></button>'}
