function renderQueue(){var el=$('queueList'),doneEl=$('queueCompletedList');if(!el)return;var todays=data.appointments.filter(function(a){return a.date===day()});var items=todays.filter(function(a){return ['Waiting','In treatment'].indexOf(a.status)>=0}).sort(function(a,b){return (a.status==='In treatment'?-1:0)-(b.status==='In treatment'?-1:0)||String(a.time||'99:99').localeCompare(String(b.time||'99:99'))});var completed=todays.filter(function(a){return a.status==='Completed'||a.status==='Left'}).sort(function(a,b){return String(b.time||'').localeCompare(String(a.time||''))});if($('queueTabCount'))$('queueTabCount').textContent=items.length;if($('queueCompletedCount'))$('queueCompletedCount').textContent=completed.length;function card(a){var isTx=a.status==='In treatment';return '<div class="apt-card compact-patient-card df-context-row apt-today" data-df-type="appointment" data-df-id="'+esc(a.id)+'" onclick="toggleCompactCard(event,this)"><div class="apt-top"><div><div class="apt-name">'+esc(a.patientName||'Patient')+'</div><div class="apt-meta">'+esc(a.time||'Walk-in')+' · '+esc(a.reason||'Visit')+'</div></div><span class="apt-status">'+esc(a.status)+'</span></div><div class="apt-actions">'+(isTx?chairsideAction('Complete queue visit','<path d="m5 12 4 4L19 6"/>','setAppointmentStatus(\''+esc(a.id)+'\',\'Completed\')'):chairsideAction('Start treatment','<path d="m8 5 11 7-11 7z"/>','setAppointmentStatus(\''+esc(a.id)+'\',\'In treatment\')'))+chairsideAction('View details','<circle cx="12" cy="12" r="9"/><path d="M12 11v5M12 7h.01"/>','openContextDetail(\'appointment\',\''+esc(a.id)+'\')')+'<span class="compact-expand-hint">More</span></div></div>'}el.innerHTML=items.length?collapsibleDateGroup('Today',items.length,items.map(card).join(''),true,'queue:today','today'):'<div class="empty">No patients waiting. Check in an appointment or add a walk-in.</div>';if(doneEl)doneEl.innerHTML=completed.length?collapsibleDateGroup('Completed today',completed.length,completed.map(card).join(''),false,'queue:completed','completed'):'<div class="empty">No completed or left queue visits today.</div>'}
function appointmentById(id){return data.appointments.find(function(a){return a.id===id})}
function renderAppointments(){var el=$('appointmentList');if(!el)return;var t=day(),mode=$('appointmentFilter')?$('appointmentFilter').value:'upcoming',all=data.appointments.slice().filter(function(x){return x.status!=='Completed'&&x.status!=='Cancelled'&&(mode==='all'||(mode==='today'&&x.date===t)||(mode==='past'&&x.date<t)||(mode==='upcoming'&&x.date>=t))}).sort(function(a,b){return String(a.date||'').localeCompare(String(b.date||''))||String(a.time||'99:99').localeCompare(String(b.time||'99:99'))});var todayA=data.appointments.filter(function(x){return x.date===t&&x.status!=='Cancelled'&&x.status!=='Completed'}),waiting=todayA.filter(function(x){return x.status==='Waiting'}).length,next=todayA.slice().sort(function(a,b){return String(a.time||'').localeCompare(String(b.time||''))}).find(function(x){return ['Scheduled','Confirmed'].indexOf(x.status)>=0});if($('aptTodayCount'))$('aptTodayCount').textContent=todayA.length;if($('aptWaitingCount'))$('aptWaitingCount').textContent=waiting;if($('aptNextTime'))$('aptNextTime').textContent=next?(next.time||'—'):'—';function card(x){var act='';if(x.status==='Scheduled'||x.status==='Confirmed')act=chairsideAction('Check in patient','<path d="m5 12 4 4L19 6"/>','setAppointmentStatus(\''+esc(x.id)+'\',\'Waiting\')');else if(x.status==='Waiting')act=chairsideAction('Start treatment','<path d="m8 5 11 7-11 7z"/>','setAppointmentStatus(\''+esc(x.id)+'\',\'In treatment\')');else if(x.status==='In treatment')act=chairsideAction('Complete visit','<path d="m5 12 4 4L19 6"/>','setAppointmentStatus(\''+esc(x.id)+'\',\'Completed\')');var urgency=x.date<day()?'apt-overdue':(x.date===day()?'apt-today':'apt-upcoming');return '<div class="apt-card compact-patient-card df-context-row '+urgency+'" data-df-type="appointment" data-df-id="'+esc(x.id)+'" onclick="toggleCompactCard(event,this)"><div class="apt-top"><div><div class="apt-name">'+esc(x.time||'—')+' · '+esc(x.patientName||'Unknown patient')+'</div><div class="apt-meta">'+esc(x.reason||'Appointment')+' · '+esc(x.date||'No date')+'</div></div><span class="apt-status">'+esc(x.status)+'</span></div>'+(x.notes?'<div class="compact-extra muted">'+esc(x.notes)+'</div>':'')+'<div class="apt-actions">'+act+chairsideAction('Details','<circle cx="12" cy="12" r="9"/><path d="M12 11v5M12 7h.01"/>','openContextDetail(\'appointment\',\''+esc(x.id)+'\')')+(['Scheduled','Confirmed','Waiting','In treatment'].indexOf(x.status)>=0?chairsideAction('Start clinical visit','<path d="M12 5v14M5 12h14"/>','openVisitFromAppointment(\''+esc(x.id)+'\')'):'')+chairsideAction('Edit appointment','<path d="M12 20h9"/><path d="M16.5 3.5a2.1 2.1 0 0 1 3 3L8 18l-4 1 1-4z"/>','openAppointmentForm(\''+esc(x.id)+'\')')+(x.patientId?chairsideAction('Open patient','<circle cx="12" cy="8" r="4"/><path d="M4 21a8 8 0 0 1 16 0"/>','openProfile(\''+esc(x.patientId)+'\')'):'')+'<span class="compact-expand-hint">More</span></div></div>'}el.innerHTML=all.length?groupChairsideRows(all,'date','time',card):'<div class="empty">No active appointments in this date range.</div>';var done=data.appointments.filter(function(x){return x.status==='Completed'});if($('appointmentCompletedCount'))$('appointmentCompletedCount').textContent=done.length;var old=$('appointmentCompletedList');if(old)old.innerHTML=done.length?groupChairsideRows(done,'date','time',card):'<div class="empty">No completed appointments yet.</div>'}
function populateAppointmentPatients(selected){var el=$('aptPatient');if(!el)return;el.innerHTML='<option value="">Select patient</option>'+data.patients.slice().sort(function(a,b){return String(a.name||'').localeCompare(String(b.name||''))}).map(function(p){return '<option value="'+esc(p.id)+'" '+(p.id===selected?'selected':'')+'>'+esc(p.name||'Unnamed patient')+' · '+esc(p.phone||p.id)+'</option>'}).join('');if(selected&&data.patients.some(function(p){return p.id===selected}))el.value=selected;}
function openWalkInQueueForm(){openAppointmentForm('',currentPatientId||'');$('appointmentFormTitle').textContent='Add Walk-in to Queue';$('aptDate').value=day();$('aptTime').value=new Date().toTimeString().slice(0,5);$('aptReason').value='Walk-in';$('aptStatus').value='Waiting';$('aptNotes').value='Walk-in patient';$('appointmentSheet').dataset.followupId=''}
function openAppointmentForm(id,pid){var a=id?appointmentById(id):null;if(!data.patients.length){alert('Add a patient first.');return}populateAppointmentPatients(a?a.patientId:(pid||currentPatientId||''));$('appointmentFormTitle').textContent=a?'Edit Appointment':'New Appointment';$('aptDate').value=a?(a.date||day()):day();$('aptTime').value=a?(a.time||''):'';$('aptReason').value=a?(a.reason||''):'';$('aptStatus').value=a?(a.status||'Scheduled'):(data.settings.defaultAppointmentStatus||'Scheduled');$('aptNotes').value=a?(a.notes||''):'';if($('aptCancelReason'))$('aptCancelReason').value=a?(a.cancelReason||''):'';if($('aptLeftReason'))$('aptLeftReason').value=a?(a.leftReason||''):'';if($('aptDelayReason'))$('aptDelayReason').value=a?(a.delayReason||''):'';$('appointmentSheet').dataset.editId=a?a.id:'';$('appointmentSheet').dataset.followupId='';$('appointmentSheet').dataset.planId=a?(a.planId||''):'';$('appointmentSheet').dataset.planItemId=a?(a.planItemId||''):'';openSheet('appointmentSheet')}
function saveAppointment(){var pid=$('aptPatient').value;if(!pid){alert('Select a patient.');return}var p=patient(pid),id=$('appointmentSheet').dataset.editId,a=id?appointmentById(id):null;if(!a){a={id:'A'+Date.now().toString(36),createdAt:new Date().toISOString()};data.appointments.push(a)}Object.assign(a,{patientId:pid,patientName:p.name,date:$('aptDate').value||day(),time:$('aptTime').value||'',reason:$('aptReason').value.trim(),status:$('aptStatus').value,notes:$('aptNotes').value.trim(),cancelReason:$('aptCancelReason')?$('aptCancelReason').value:'',leftReason:$('aptLeftReason')?$('aptLeftReason').value:'',delayReason:$('aptDelayReason')?$('aptDelayReason').value:'',followupId:a.followupId||$('appointmentSheet').dataset.followupId||'',planId:a.planId||$('appointmentSheet').dataset.planId||'',planItemId:a.planItemId||$('appointmentSheet').dataset.planItemId||'',visitId:a.visitId||''});if(a.planId&&a.planItemId){var linkedPlan=data.plans.find(function(pl){return pl.id===a.planId});var linkedItem=linkedPlan&&(linkedPlan.items||[]).find(function(it){return it.id===a.planItemId});if(linkedItem&&linkedItem.status!=='Completed'&&['Cancelled','No-show'].indexOf(a.status)<0)linkedItem.status='Scheduled';}if(a.followupId||$('appointmentSheet').dataset.followupId){var linkedFu=followupById(a.followupId||$('appointmentSheet').dataset.followupId);if(linkedFu){linkedFu.appointmentId=a.id;if(linkedFu.status!=='Completed')linkedFu.status='Scheduled';linkedFu.updatedAt=new Date().toISOString()}}save();closeSheet('appointmentSheet');$('appointmentSheet').dataset.editId='';$('appointmentSheet').dataset.followupId='';$('appointmentSheet').dataset.planId='';$('appointmentSheet').dataset.planItemId='';render();toast('Appointment saved')}
function setAppointmentStatus(id,status){var a=appointmentById(id);if(!a)return;a.status=status;if(a.followupId){var f=followupById(a.followupId);if(f){if(status==='Cancelled'||status==='No-show'){if(f.status!=='Completed')f.status='Pending';f.appointmentId=''}else if(status==='Waiting'||status==='In treatment'){f.appointmentId=a.id}f.updatedAt=new Date().toISOString()}}save();render();toast(status==='Waiting'?'Patient checked in':status==='In treatment'?'Treatment started':status==='Completed'?'Visit completed':'Appointment updated')}
function deleteAppointment(id){if(!confirm('Delete this appointment?'))return;var a=appointmentById(id);if(a&&a.followupId){var f=followupById(a.followupId);if(f){f.appointmentId='';if(f.status==='Scheduled')f.status='Pending';f.updatedAt=new Date().toISOString()}}data.appointments=data.appointments.filter(function(a){return a.id!==id});save();render();toast('Appointment deleted')}

