function renderReminders(q){var home=$('reminderList'),page=$('reminderPageList');if(!home&&!page)return;q=(q||'').trim().toLowerCase();var all=data.reminders.slice().sort(function(a,b){return String(a.dueDate||'').localeCompare(String(b.dueDate||''))||String(a.dueTime||'99:99').localeCompare(String(b.dueTime||'99:99'))}),pending=all.filter(function(r){return r.status!=='Done'&&r.status!=='Completed'}),completed=all.filter(function(r){return r.status==='Done'||r.status==='Completed'}),todayN=pending.filter(function(r){return r.dueDate===day()}).length,overdue=pending.filter(function(r){return r.dueDate<day()}).length;if($('remPending'))$('remPending').textContent=pending.length;if($('remToday'))$('remToday').textContent=todayN;if($('remOverdue'))$('remOverdue').textContent=overdue;if($('reminderTabCount'))$('reminderTabCount').textContent=pending.length;if($('reminderCompletedCount'))$('reminderCompletedCount').textContent=completed.length;if($('reminderSummary'))$('reminderSummary').textContent=pending.length?(overdue+' overdue · '+todayN+' due today'):'No pending clinic reminders';function matches(r){var p=patient(r.patientId);return !q||[r.patientName,r.patientId,r.type,r.note,p?p.phone:''].join(' ').toLowerCase().indexOf(q)>=0}function card(r){var late=r.status==='Pending'&&r.dueDate<day(),dueToday=r.status==='Pending'&&r.dueDate===day();return '<div class="apt-card reminder-card compact-patient-card df-context-row '+(late?'rem-overdue ':'')+(dueToday?'rem-today':'')+'\" data-df-type=\"reminder\" data-df-id=\"'+esc(r.id)+'\" onclick=\"toggleCompactCard(event,this)\"><div class=\"apt-top\"><div><div class="apt-name">'+esc(r.patientName||'Patient')+'</div><div class="apt-meta">'+esc(r.type)+' · '+esc(r.dueDate||'No date')+(r.dueTime?' · '+esc(r.dueTime):'')+'</div></div><span class="apt-status">'+esc(r.status)+'</span></div>'+(r.note?'<div class="compact-extra muted" style="margin-top:4px">'+esc(r.note)+'</div>':'')+'<div class="apt-actions">'+chairsideAction('Details','<circle cx="12" cy="12" r="9"/><path d="M12 11v5M12 7h.01"/>','openContextDetail(\'reminder\',\''+esc(r.id)+'\')')+(r.status!=='Done'&&r.status!=='Completed'?chairsideAction('Complete reminder','<path d="m5 12 4 4L19 6"/>','setReminderStatus(\''+esc(r.id)+'\',\'Done\')'):'')+(r.status!=='Snoozed'&&r.status!=='Done'&&r.status!=='Completed'?chairsideAction('Snooze reminder','<circle cx="12" cy="12" r="9"/><path d="M12 7v5l3 2"/>','setReminderStatus(\''+esc(r.id)+'\',\'Snoozed\')'):'')+chairsideAction('Edit reminder','<path d="M12 20h9"/><path d="M16.5 3.5a2.1 2.1 0 0 1 3 3L8 18l-4 1 1-4z"/>','openReminderForm(\''+esc(r.id)+'\')')+'<span class=\"compact-expand-hint\">More</span></div></div>'}var arr=pending.filter(matches),done=completed.filter(matches);if(home)home.innerHTML=pending.length?pending.slice(0,3).map(function(r){return '<div class="row home-compact-row"><div><b>'+esc(r.patientName||'Patient')+'</b><div class="muted">'+esc(r.type)+' · '+esc(chairsideDateLabel(r.dueDate))+(r.dueTime?' · '+esc(r.dueTime):'')+'</div></div><button class="btn ghost" onclick="openContextDetail(\'reminder\',\''+esc(r.id)+'\')">›</button></div>'}).join('')+'<button class="btn ghost" style="width:100%;margin-top:6px" onclick="switchView(\'reminders\')">View follow-ups & reminders →</button>':'<div class="empty">No pending clinic reminders.</div>';if(page)page.innerHTML=arr.length?groupChairsideRows(arr,'dueDate','dueTime',card):'<div class="empty">No active reminders.</div>';var ce=$('reminderCompletedList');if(ce)ce.innerHTML=done.length?groupChairsideRows(done,'dueDate','dueTime',card):'<div class="empty">No completed reminders yet.</div>'}
function backupCounts(d){return{patients:(d.patients||[]).length,visits:(d.visits||[]).length,plans:(d.plans||[]).length,bills:(d.bills||[]).length,appointments:(d.appointments||[]).length,records:(d.records||[]).length,reminders:(d.reminders||[]).length,followups:(d.followups||[]).length,templates:(d.templates||[]).length}}
function snapshotPayload(){let c=JSON.parse(JSON.stringify(data));c.backups=[];return c}
function createSnapshot(){try{let payload=snapshotPayload(),snap={id:'BK'+Date.now().toString(36),createdAt:new Date().toISOString(),label:'Safety snapshot',counts:backupCounts(payload),payload:payload};data.backups=(data.backups||[]).filter(function(x){return x&&x.payload}).slice(-7);data.backups.push(snap);save();renderBackupCenter();toast('Safety snapshot created')}catch(e){console.error(e);alert('Could not create safety snapshot.')}}
function renderBackupCenter(){let count=$('backupCount'),health=$('dataHealth'),list=$('backupList');if(!count&&!health&&!list)return;let arr=(data.backups||[]).slice().reverse();if(count)count.textContent=arr.length;if(health){let issues=[];if(!Array.isArray(data.patients))issues.push('patients');if(!Array.isArray(data.visits))issues.push('visits');if(!Array.isArray(data.plans))issues.push('plans');if(!Array.isArray(data.bills))issues.push('bills');if(!Array.isArray(data.appointments))issues.push('appointments');if(!Array.isArray(data.records))issues.push('records');if(!Array.isArray(data.reminders))issues.push('reminders');if(!Array.isArray(data.followups))issues.push('followups');health.textContent=issues.length?'Check needed':'Healthy';health.className=issues.length?'danger health-ok':'health-ok'}if(list)list.innerHTML=arr.length?arr.map(function(b){let c=b.counts||{};return '<div class="backup-item"><b>'+esc(b.label)+'</b><div class="muted">'+esc(new Date(b.createdAt).toLocaleString())+' · '+esc(String(c.patients||0))+' patients · '+esc(String(c.visits||0))+' visits · '+esc(String(c.bills||0))+' bills</div><div class="actions"><button class="btn secondary" onclick="restoreSnapshot(\''+esc(b.id)+'\')">Restore</button><button class="btn danger" onclick="deleteSnapshot(\''+esc(b.id)+'\')">Delete</button></div></div>'}).join(''):'<div class="empty">No safety snapshots yet.</div>'}
function validateBackupObject(x){if(!x||typeof x!=='object')return false;let keys=['patients','visits','plans','bills','appointments','records','reminders','templates','settings'];return keys.every(function(k){return k==='settings'||Array.isArray(x[k])})&&x.settings&&typeof x.settings==='object'}
function validateCurrentData(){var structural=validateBackupObject(data),collections=[['patients',data.patients||[]],['visits',data.visits||[]],['plans',data.plans||[]],['bills',data.bills||[]],['appointments',data.appointments||[]],['records',data.records||[]],['reminders',data.reminders||[]],['followups',data.followups||[]]],idSets={},duplicates=0,missingIds=0,brokenPatientRefs=0,brokenLinks=0,invalidMoney=0;collections.forEach(function(pair){var seen=new Set();idSets[pair[0]]=new Set();pair[1].forEach(function(x){if(!x||!x.id){missingIds++;return}var id=String(x.id);if(seen.has(id))duplicates++;seen.add(id);idSets[pair[0]].add(id)})});var pids=idSets.patients;['visits','plans','bills','appointments','records','reminders','followups'].forEach(function(k){(data[k]||[]).forEach(function(x){if(x&&x.patientId&&!pids.has(String(x.patientId)))brokenPatientRefs++})});function checkRef(value,set){if(value&&!set.has(String(value)))brokenLinks++}(data.visits||[]).forEach(function(v){checkRef(v.appointmentId,idSets.appointments);checkRef(v.billId,idSets.bills);checkRef(v.reminderId,idSets.reminders);(Array.isArray(v.linkedPlanIds)?v.linkedPlanIds:[]).forEach(function(id){checkRef(id,idSets.plans)})});(data.bills||[]).forEach(function(b){checkRef(b.visitId,idSets.visits);checkRef(b.linkedVisitId,idSets.visits);checkRef(b.linkedPlanId,idSets.plans);(Array.isArray(b.items)?b.items:[]).forEach(function(it){if(!Number.isFinite(Number(it.amount))||Number(it.amount)<0)invalidMoney++});(Array.isArray(b.payments)?b.payments:[]).forEach(function(pm){if(!Number.isFinite(Number(pm.amount))||Number(pm.amount)<0)invalidMoney++})});(data.appointments||[]).forEach(function(a){checkRef(a.visitId,idSets.visits)});(data.followups||[]).forEach(function(f){checkRef(f.visitId,idSets.visits);checkRef(f.appointmentId,idSets.appointments)});(data.reminders||[]).forEach(function(r){checkRef(r.visitId,idSets.visits);checkRef(r.billId,idSets.bills)});(data.plans||[]).forEach(function(pl){(Array.isArray(pl.linkedVisitIds)?pl.linkedVisitIds:[]).forEach(function(id){checkRef(id,idSets.visits)})});var ok=structural&&missingIds===0&&duplicates===0&&brokenPatientRefs===0&&brokenLinks===0&&invalidMoney===0;if($('dataHealth')){$('dataHealth').textContent=ok?'Healthy':(structural?'Review needed':'Structure issue');$('dataHealth').className=ok?'health-ok':'danger health-ok'}alert('Workflow/data check complete. No data was changed.\n\nStructural format: '+(structural?'OK':'Needs review')+'\nRecords missing IDs: '+missingIds+'\nDuplicate IDs: '+duplicates+'\nBroken patient references: '+brokenPatientRefs+'\nBroken internal links (visit/bill/appointment/follow-up/plan): '+brokenLinks+'\nInvalid bill/payment amounts: '+invalidMoney+'\n\nA clean result is a basic consistency check, not a guarantee of backup integrity. Export an external JSON backup regularly.');return ok}
function restoreSnapshot(id){let b=(data.backups||[]).find(function(x){return x.id===id});if(!b||!b.payload)return;if(!confirm('Restore this snapshot? A new safety snapshot will be created first.'))return;try{let current=snapshotPayload();data.backups=(data.backups||[]).filter(function(x){return x&&x.payload}).slice(-7);data.backups.push({id:'BK'+Date.now().toString(36),createdAt:new Date().toISOString(),label:'Before restore',counts:backupCounts(current),payload:current});let restored=normalize(JSON.parse(JSON.stringify(b.payload)));restored.backups=data.backups;data=restored;save();render();toast('Snapshot restored')}catch(e){console.error(e);alert('Snapshot restore failed. Current data was not safely replaced.')}}
function deleteSnapshot(id){if(!confirm('Delete this saved snapshot?'))return;data.backups=(data.backups||[]).filter(function(x){return x.id!==id});save();renderBackupCenter();toast('Snapshot deleted')}
function auditBackupObject(x){var issues=[];var keys=['patients','visits','plans','bills','appointments','records','reminders','followups'];var sets={};keys.forEach(function(k){var seen=new Set();sets[k]=seen;(Array.isArray(x[k])?x[k]:[]).forEach(function(row){if(!row||!row.id)issues.push(k+': record missing an ID');else if(seen.has(String(row.id)))issues.push(k+': duplicate ID '+row.id);else seen.add(String(row.id))})});var patientIds=sets.patients;['visits','plans','bills','appointments','records','reminders','followups'].forEach(function(k){(Array.isArray(x[k])?x[k]:[]).forEach(function(row){if(row&&row.patientId&&!patientIds.has(String(row.patientId)))issues.push(k+': patient reference not found')})});(Array.isArray(x.bills)?x.bills:[]).forEach(function(b){(Array.isArray(b&&b.items)?b.items:[]).forEach(function(it){if(!Number.isFinite(Number(it.amount))||Number(it.amount)<0)issues.push('bill: invalid item amount')});(Array.isArray(b&&b.payments)?b.payments:[]).forEach(function(pm){if(!Number.isFinite(Number(pm.amount))||Number(pm.amount)<0)issues.push('bill: invalid payment amount')})});return issues}
function importBackupFile(e){let f=e&&e.target&&e.target.files?e.target.files[0]:null;if(!f)return;let r=new FileReader();r.onload=function(){try{let raw=JSON.parse(r.result),candidate=raw&&raw.data&&typeof raw.data==='object'?raw.data:raw;if(!validateBackupObject(candidate))throw new Error('Invalid structure');var issues=auditBackupObject(candidate);var counts=backupCounts(candidate);var summary='Import this backup and replace current clinic data?\n\n'+counts.patients+' patients · '+counts.visits+' visits · '+counts.bills+' bills\n';if(issues.length)summary+='\nWarning: '+issues.length+' data issue(s) detected. First few:\n• '+issues.slice(0,4).join('\n• ')+'\n\nReview the backup carefully before continuing. ';summary+='\nA safety snapshot of current data will be created first.';if(!confirm(summary))return;let current=snapshotPayload();data.backups=(data.backups||[]).filter(function(x){return x&&x.payload}).slice(-7);data.backups.push({id:'BK'+Date.now().toString(36),createdAt:new Date().toISOString(),label:'Before import',counts:backupCounts(current),payload:current});let imported=normalize(JSON.parse(JSON.stringify(candidate)));imported.backups=data.backups;var previous=data;data=imported;if(!save()){data=previous;alert('Import could not be saved to device storage. Current in-memory data was restored. Do not reload; export a backup and free storage before retrying.');return}render();alert('Backup imported successfully.\n\nDetected data issues: '+issues.length+(issues.length?'\nRun Data check and review the imported records.':''))}catch(err){console.error(err);alert('Invalid DentalFlow backup file. No data was changed.')}finally{e.target.value=''}};r.readAsText(f)}
function safeResetData(){if(!confirm('Reset ALL DentalFlow data on this device?'))return;if(!confirm('This cannot be undone unless you have a backup. Create a safety snapshot now and continue?'))return;try{let current=snapshotPayload(),snaps=(data.backups||[]).filter(function(x){return x&&x.payload}).slice(-7);snaps.push({id:'BK'+Date.now().toString(36),createdAt:new Date().toISOString(),label:'Before reset',counts:backupCounts(current),payload:current});let fresh=blank();fresh.backups=snaps.slice(-8);data=fresh;save();render();alert('All active clinic data has been reset. The pre-reset snapshot is still available in Backup & Data Safety.')}catch(e){console.error(e);alert('Reset failed.')}}

/* ===== DentalFlow V11 Advanced Search & Clinical Timeline ===== */
function renderAdvancedSearch(){
  var el=$('advancedResults'); if(!el)return;
  var q=(($('advSearch')&&$('advSearch').value)||'').trim().toLowerCase();
  var type=(($('advType')&&$('advType').value)||'all');
  if(!q){el.innerHTML='<div class="empty">Start typing to search.</div>';return}
  var out=[];
  function hit(arr,fields){return arr.some(function(v){return fields.map(function(k){return v[k]||''}).join(' ').toLowerCase().indexOf(q)>=0})}
  if(type==='all'||type==='patient') data.patients.forEach(function(p){if(hit([p],['name','phone','id','address','medical']))out.push({date:p.createdAt||'',html:'<b>Patient · '+esc(p.name)+'</b><div class="muted">'+esc(p.id)+' · '+esc(p.phone||'')+'</div><div class="actions"><button class="btn secondary" onclick="openProfile(\''+esc(p.id)+'\')">Patient</button></div>'})});
  if(type==='all'||type==='visit') data.visits.forEach(function(v){if(hit([v],['patientName','patientId','reason','chiefComplaint','history','examination','diagnosis','treatmentDone','advice','prescription']))out.push({date:v.date,html:'<b>Clinical visit · '+esc(v.patientName||patient(v.patientId)?.name||v.patientId)+'</b><div class="muted">'+esc(v.date)+' · '+esc(v.diagnosis||v.reason||'Visit')+'</div><div class="actions"><button class="btn secondary" onclick="openProfile(\''+esc(v.patientId)+'\')">Patient</button></div>'})});
  if(type==='all'||type==='record') data.records.forEach(function(r){var pn=patient(r.patientId);if(hit([r],['title','type','details','patientId'])||((pn?.name||'')+' '+(pn?.phone||'')).toLowerCase().indexOf(q)>=0)out.push({date:r.date,html:'<b>Record · '+esc(r.title)+'</b><div class="muted">'+esc(r.type)+' · '+esc(pn?pn.name:r.patientId)+'</div><div class="actions"><button class="btn secondary" onclick="openRecordForm(\''+esc(r.id)+'\')">Open record</button></div>'})});
  if(type==='all'||type==='appointment') data.appointments.forEach(function(a){if(hit([a],['patientName','patientId','reason','status','notes','date','time']))out.push({date:a.date,html:'<b>Appointment · '+esc(a.patientName)+'</b><div class="muted">'+esc(a.date)+' · '+esc(a.time)+' · '+esc(a.status)+'</div><div class="actions"><button class="btn secondary" onclick="openAppointmentForm(\''+esc(a.id)+'\')">Open</button></div>'})});
  if(type==='all'||type==='plan') data.plans.forEach(function(pl){var pn=patient(pl.patientId);var text=[pl.title,pl.status,pl.notes,pn?pn.name:'',pl.patientId].join(' ').toLowerCase();if(text.indexOf(q)>=0)out.push({date:pl.createdAt,html:'<b>Treatment plan · '+esc(pl.title)+'</b><div class="muted">'+esc(pn?pn.name:pl.patientId)+' · '+esc(pl.status)+'</div><div class="actions"><button class="btn secondary" onclick="openProfile(\''+esc(pl.patientId)+'\')">Patient</button></div>'})});
  if(type==='all'||type==='bill') data.bills.forEach(function(b){if(hit([b],['id','patientName','patientId','title','notes'])||((b.items||[]).map(function(i){return i.service+' '+i.tooth}).join(' ')).toLowerCase().indexOf(q)>=0)out.push({date:b.date,html:'<b>Billing · '+esc(b.patientName)+'</b><div class="muted">'+esc(b.id)+' · '+esc(b.title)+' · '+esc(b.status)+'</div><div class="actions"><button class="btn secondary" onclick="switchView(\'billing\')">Billing</button></div>'})});
  out.sort(function(a,b){return String(b.date||'').localeCompare(String(a.date||''))});
  el.innerHTML=out.length?out.map(function(x){return '<div class="card">'+x.html+'</div>'}).join(''):'<div class="empty">No matching results.</div>';
}
function renderPatientTimeline(pid){
  var el=$('patientTimeline');if(!el)return;var a=[];
  data.visits.filter(function(v){return v.patientId===pid}).forEach(function(v){a.push({date:v.date,time:v.time||'',kind:'Clinical visit',title:v.diagnosis||v.reason||'Clinical visit',sub:v.treatmentDone||v.chiefComplaint||'',type:'visit',id:v.id})});
  data.plans.filter(function(v){return v.patientId===pid}).forEach(function(v){a.push({date:String(v.createdAt||'').slice(0,10),time:'',kind:'Treatment plan',title:v.title,sub:v.status,type:'plan',id:v.id})});
  data.records.filter(function(v){return v.patientId===pid}).forEach(function(v){a.push({date:v.date,time:'',kind:'Patient record',title:v.title,sub:v.type,type:'record',id:v.id})});
  data.appointments.filter(function(v){return v.patientId===pid}).forEach(function(v){a.push({date:v.date,time:v.time||'',kind:'Appointment',title:v.reason||'Appointment',sub:v.status,type:'appointment',id:v.id})});
  data.bills.filter(function(v){return v.patientId===pid}).forEach(function(v){a.push({date:v.date,time:'',kind:'Billing',title:v.title||'Bill',sub:'₹ '+billTotal(v).toLocaleString('en-IN')+' · '+v.status,type:'bill',id:v.id})});
  data.reminders.filter(function(v){return v.patientId===pid}).forEach(function(v){a.push({date:v.dueDate,time:v.dueTime||'',kind:'Reminder',title:v.type||'Follow-up',sub:v.status+(v.note?' · '+v.note:''),type:'reminder',id:v.id})});
  a.sort(function(x,y){return (String(y.date)+' '+String(y.time)).localeCompare(String(x.date)+' '+String(x.time))});
  el.innerHTML=a.length?a.map(function(x){return '<button type="button" class="visit-card timeline-entry" onclick="openContextDetail(\''+x.type+'\',\''+esc(x.id)+'\')"><span class="timeline-entry-main"><span class="muted">'+esc(x.date||'—')+' · '+esc(x.kind)+'</span><b>'+esc(x.title)+'</b>'+(x.sub?'<span class="muted">'+esc(x.sub)+'</span>':'')+'</span><span class="timeline-chevron">›</span></button>'}).join(''):'<div class="empty">No timeline activity yet.</div>';
}
/* Home paired workspaces have their own independent swipe state. */
(function(){document.querySelectorAll('.home-workspace').forEach(function(root){var sx=0,sy=0;root.addEventListener('touchstart',function(e){if(!e.touches||e.touches.length!==1)return;sx=e.touches[0].clientX;sy=e.touches[0].clientY},{passive:true});root.addEventListener('touchend',function(e){if(!e.changedTouches||e.changedTouches.length!==1)return;var dx=e.changedTouches[0].clientX-sx,dy=e.changedTouches[0].clientY-sy;if(Math.abs(dx)<60||Math.abs(dx)<Math.abs(dy)*1.3)return;var panes=Array.from(root.querySelectorAll('.home-paired-pane')),active=panes.findIndex(function(p){return p.classList.contains('active')});var next=dx<0?Math.min(panes.length-1,active+1):Math.max(0,active-1);if(next!==active)selectHomePane(root.querySelector('.home-paired-tabs').getAttribute('aria-label').indexOf('appointments')>=0?'schedule':'followups',panes[next].id)},{passive:true})})})();
/* Primary navigation swipe: only on the main workspace, never inside forms, sheets or horizontal controls. */
(function(){var order=['home','patients','visits','billing','more'],sx=0,sy=0,valid=false;document.addEventListener('touchstart',function(e){if(!e.touches||e.touches.length!==1){valid=false;return}var t=e.target;if(t.closest('input,textarea,select,button,.overlay,.menu-overlay,.chairside-tabs,.home-paired-tabs,.tooth-grid,.plan-template,[data-no-nav-swipe]')){valid=false;return}var active=document.querySelector('.view.active');if(!active){valid=false;return}sx=e.touches[0].clientX;sy=e.touches[0].clientY;valid=true},{passive:true});document.addEventListener('touchend',function(e){if(!valid||!e.changedTouches||e.changedTouches.length!==1)return;valid=false;var dx=e.changedTouches[0].clientX-sx,dy=e.changedTouches[0].clientY-sy;if(Math.abs(dx)<95||Math.abs(dx)<Math.abs(dy)*1.5)return;var active=document.querySelector('.view.active');if(!active)return;var idx=order.indexOf(active.id);if(idx<0)return;var next=dx<0?Math.min(order.length-1,idx+1):Math.max(0,idx-1);if(next!==idx)switchView(order[next])},{passive:true})})();


